import"./chunk-WOT6VMZA.js";var l=(e,t,a,i,n,r,o,s,c,h,p,m,d,u)=>({challenge:{prompt:e,check:t},...d?{presets:d}:{},...u?{mentorTips:u}:{},yourNumbers:a,cutaway:i,watch:[{title:"1. Wide view",caption:"1/5 Wide shot: "+n,act:r},{title:"2. Close-up",caption:"2/5 Close-up: "+o,act:s},{title:"3. Cut-away",caption:"3/5 Cut-away: "+c,cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: "+h,act:p},{title:"5. Your turn",caption:"5/5 Your turn: Drag to orbit in 3D, switch stations, or explode the parts.",cutaway:!1}],idealised:m}),g={videotrack:{challenge:{prompt:"Calibrate the wall tiles to a real wall scale and mark the tossed ball frame-by-frame\u2014how do equal-time height gaps reveal whether speed is changing?",check:e=>e.tab(0)===1&&Math.abs(e.num("Tile scale",10)-10)<.5},presets:[{name:"10 cm Wall Tiles",prompt:"Standard bathroom/school tile scale.",state:{tabs:[0],sliders:{"Tile scale":10}}},{name:"0.10 s Strobe Marks",prompt:"Inspect shrinking upward gaps between ticks.",state:{tabs:[1],sliders:{"Tile scale":10}}}],mentorTips:{openPlay:"Ask Kym whether the ball slows down smoothly or loses speed in sudden jumps.",misconception:"Thinking equal distances in video frames mean constant acceleration instead of constant speed.",dinnerQuestion:"If you photograph a falling coin under a blinking lamp at Chowpatty, why do successive shadows pull farther apart?",cambridgeUnit:"Unit 1 \xB7 Motion & Video Kinematics"},yourNumbers:e=>`Tile = ${e.num("Tile scale",10)} cm | Demo marks: \u0394t = 0.100 s. For a clip, choose 0.100 s, 0.050 s, or \u0394t = 1/fps using the clip\u2019s selected fps. Calibrate before using centimetres.`,cutaway:"A clip supplies image samples and timestamps. Exposure duration and actual frame timing depend on the camera; selected fps must match the clip. The demo uses fixed 0.100 s marks.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: A ball tossed past wall tiles gives both a clock (frames) and a ruler (tiles).",act:e=>{e.selectTab(0,0),e.setSlider("Tile scale",10)}},{title:"2. Close-up",caption:"2/5 Close-up: Marking every 0.10 s shows the gaps shrinking on the way up as gravity slows the ball.",act:e=>e.selectTab(0,1)},{title:"3. Cut-away",caption:"3/5 Cut-away: Inside the camera shutter, exposure time can blur the ball; clip frame intervals and marking errors limit measurement.",cutaway:!0,act:e=>e.selectTab(0,2)},{title:"4. Side-on trend",caption:"4/5 Trend: For a loaded clip, every-frame gaps can be too small to measure reliably. Demo points remain 0.100 s apart.",act:e=>e.selectTab(0,3)},{title:"5. Your turn",caption:"5/5 Your turn: Change the tile scale or load your own clip to measure speed.",cutaway:!1}],idealised:"The demo toss ignores air drag and lens barrel distortion, which curves straight tile lines near the edges of a real phone camera."},graphwalk:{challenge:{prompt:"Walk forward, pause, and turn back toward the far wall of the corridor\u2014how does the position\u2013time slope distinguish moving from standing still?",check:e=>e.tab(0)===1&&Math.abs(e.num("Corridor position",0)-6.5)<=.25},presets:[{name:"Replay Reference Walk",prompt:"Inspect slope changes in Fig 1.2.",state:{tabs:[0],sliders:{"Corridor position":0}}},{name:"Mid-Corridor Pause",prompt:"Stand near 4.0 m and watch time run flat.",state:{tabs:[1],sliders:{"Corridor position":4}}}],mentorTips:{openPlay:"Cover the corridor graphic and guess Kym\u2019s motion purely from the graph slope first.",misconception:"Reading a position\u2013time graph as if it showed the hill shape or speed-vs-time directly.",dinnerQuestion:"On the Marine Drive promenade, what does a flat horizontal stretch on your distance\u2013time graph mean?",cambridgeUnit:"Unit 1 \xB7 Position\u2013Time Graphs"},yourNumbers:e=>{let t=e.num("Corridor position",0),a=e.tab(0)===1?"walking live":"replaying Fig 1.2";return`x(t) = ${t.toFixed(1)} m from classroom door  |  slope = \u0394x \xF7 \u0394t = velocity (${a})`},cutaway:"A real ultrasonic rangefinder can infer distance from an echo delay: x = sound speed \xD7 delay / 2. This widget uses a position slider, not a connected sensor.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: The corridor and position\u2013time graph represent the same walk.",act:e=>e.selectTab(0,0)},{title:"2. Close-up",caption:"2/5 Close-up: A steeper line means covering more metres each second.",act:e=>{e.selectTab(0,1),e.setSlider("Corridor position",3)}},{title:"3. Cut-away",caption:"3/5 Cut-away: How a motion sensor turns echo delay into a live position dot.",cutaway:!0,act:e=>e.setSlider("Corridor position",5.5)},{title:"4. Side-on trend",caption:"4/5 Trend: Standing still draws a flat horizontal line\u2014time keeps moving even when you do not.",act:e=>e.setSlider("Corridor position",6.5)},{title:"5. Your turn",caption:"5/5 Your turn: Drag the corridor slider to match or invent a walk.",cutaway:!1}],idealised:"Your position is treated as a single point; a real walker sways slightly with every step."},freefall:{challenge:{prompt:"Replay the simulated accelerometer trace: identify held (~9.8 m/s\xB2), freely falling (~0), and caught (a short peak).",check:e=>e.interacted||e.watched},presets:[{name:"Simulated Drop Trace",prompt:"Compare supported weight vs weightless free fall.",state:{tabs:[]}}],mentorTips:{openPlay:"Ask Kym why the reading drops to ZERO while falling instead of jumping up.",misconception:"Thinking a free-fall accelerometer measures velocity downward rather than contact support force.",dinnerQuestion:"Why does an astronaut inside the International Space Station float if Earth\u2019s gravity up there is still ~90% as strong as in Mumbai?",cambridgeUnit:"Unit 1 \xB7 Free Fall & Weightlessness"},yourNumbers:()=>"Accelerometer signal: supported \u2248 9.8 m/s\xB2; freely falling \u2248 0. This is a simulated sensor trace, not a velocity graph.",cutaway:"Inside the phone MEMS accelerometer: a microscopic silicon proof-mass on springs relaxes to zero deflection during free fall.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: The simulated accelerometer reads about 9.8 m/s\xB2 when supported and nearly zero while falling."},{title:"2. Close-up",caption:"2/5 Close-up: The low-signal interval identifies free fall; the catching support creates the short peak."},{title:"3. Cut-away",caption:"3/5 Cut-away: Inside the falling phone, the tiny silicon spring is weightless until the cushion catches it.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: A near-zero accelerometer reading during free fall does not mean that gravitational acceleration is zero."},{title:"5. Your turn",caption:"5/5 Your turn: Replay the simulated trace; the motion sensor is a separate optional measurement.",cutaway:!1,act:e=>e.clickBtn("Replay")}],idealised:"The simulated trace illustrates support, free fall and a catch. A real sensor has orientation, sampling and calibration limits."},airfall:{challenge:{prompt:"Make the feather and coin hit the bottom at the exact same instant\u2014discover which condition makes mass stop mattering.",check:e=>e.num("Air",1)<=.02},presets:[{name:"Room Air",prompt:"Compare heavy coin vs light feather in 100% air.",state:{sliders:{Air:1}}},{name:"Vacuum Tube",prompt:"Pump out all air so only gravity acts.",state:{sliders:{Air:0}}}],mentorTips:{openPlay:"Let her drop the feather and coin in full air, then slowly pump air out step by step.",misconception:"Believing heavier objects inherently fall faster because gravity pulls harder (forgetting larger mass also resists acceleration).",dinnerQuestion:"On the Moon, if you dropped a hammer and a tissue side by side, which lands first and why?",cambridgeUnit:"Unit 3 \xB7 Forces & Gravity"},yourNumbers:e=>`F_net = mg \u2212 \xBD\u03C1C_DAv\xB2 | air density = ${Math.round(e.num("Air",1)*100)}% of the reference. At release v = 0, so drag = 0 and both initial accelerations are g = 9.8 m/s\xB2.`,cutaway:"Inside the tube: at full air, ~2.5 \xD7 10\xB2\u2075 N\u2082 and O\u2082 molecules per m\xB3 collide with the feather\u2019s barbs; pumping them out leaves only gravity.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: In normal room air, the coin drops like a stone while the feather drifts.",act:e=>{e.setSlider("Air",1),e.clickBtn("Drop")}},{title:"2. Close-up",caption:"2/5 Close-up: At 40% of the reference air density, the same speed produces 40% of the quadratic drag.",act:e=>{e.setSlider("Air",.4),e.clickBtn("Drop")}},{title:"3. Cut-away",caption:"3/5 Cut-away: At the microscopic scale, air drag is billions of gas molecules bouncing off the falling surface.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: In a vacuum (Air = 0), mass cancels out of F = m g and both fall side by side.",act:e=>{e.setSlider("Air",0),e.clickBtn("Drop")}},{title:"5. Your turn",caption:"5/5 Your turn: Compare pairs of objects at any air density.",cutaway:!1}],idealised:"Drag is modelled as quadratic vertical resistance without the fluttering vortices a real feather sheds in air."},projectile:{challenge:{prompt:"Fire horizontally (0\xB0) and discover what launch speed lands the flicked coin at about 1.17 m away.",check:e=>Math.abs(e.num("Launch angle",0))<1&&Math.abs(e.num("Sideways",2)-3)<.1},presets:[{name:"Drop vs Flick",prompt:"Zero angle compare: horizontal flick vs vertical drop.",state:{sliders:{"Launch angle":0,Sideways:2}}},{name:"45\xB0 Range",prompt:"Launch upward at 45\xB0 to compare flight time.",state:{sliders:{"Launch angle":45,Sideways:3}}}],mentorTips:{openPlay:"Ask her to watch only the vertical heights of the two coins, ignoring sideways motion.",misconception:"Thinking a fast sideways throw stays in the air longer before hitting the floor.",dinnerQuestion:"Why does a bullet fired horizontally from shoulder height hit flat ground at the exact same moment as one dropped from your hand?",cambridgeUnit:"Unit 3 \xB7 Independent Components"},yourNumbers:e=>{let t=e.num("Sideways",2),i=e.num("Launch angle",0)*Math.PI/180,n=t*Math.cos(i),r=t*Math.sin(i),s=(r+Math.sqrt(r*r+2*9.8*.75))/9.8,c=n*s;return`x = v_x t = ${n.toFixed(2)} \xD7 ${s.toFixed(2)} s = ${c.toFixed(2)} m  |  y = h\u2080 + v_y\u2080t \u2212 \xBDgt\xB2 (h\u2080 = 0.75 m)`},cutaway:"Inside the two-component split: the horizontal velocity arrow v_x stays the exact same length all the way across while v_y grows by 9.8 m/s every second.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: The dropped coin and the horizontally flicked coin fall through the same height lines at the same instants.",act:e=>{e.setSlider("Launch angle",0),e.setSlider("Sideways",2),e.clickBtn("Launch")}},{title:"2. Close-up",caption:"2/5 Close-up: Doubling the horizontal speed doubles the landing distance without changing the flight time.",act:e=>{e.setSlider("Sideways",3),e.clickBtn("Launch")}},{title:"3. Cut-away",caption:"3/5 Cut-away: Gravity pulls only downward; nothing pushes or slows the sideways motion.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Tilting the launch upward adds initial vertical speed, keeping the coin in the air longer.",act:e=>{e.setSlider("Launch angle",20),e.clickBtn("Launch")}},{title:"5. Your turn",caption:"5/5 Your turn: Aim the coin to hit your target distance.",cutaway:!1}],idealised:"Air resistance and coin spin (Magnus lift) are omitted, so horizontal velocity remains strictly constant."},ramp:{challenge:{prompt:"Set friction to zero and make the second ramp gentle (10\xB0)\u2014compare how far along the slope the puck slides to regain its 1.0 m starting height.",check:e=>e.num("Friction",0)<=.01&&Math.abs(e.num("Second ramp angle",20)-10)<=1},presets:[{name:"Symmetric 30\xB0",prompt:"Frictionless equal-angle recovery.",state:{sliders:{Friction:0,"Second ramp angle":30}}},{name:"Galileo Flat (0\xB0)",prompt:"Flatten the second ramp completely.",state:{sliders:{Friction:0,"Second ramp angle":0}}}],mentorTips:{openPlay:"Ask how high the puck climbs on the far side before touching the friction slider.",misconception:"Assuming an object needs an ongoing push just to keep sliding on a level frictionless floor.",dinnerQuestion:"If you flattened Galileo\u2019s second ramp all the way to horizontal with zero friction, when would the marble ever stop?",cambridgeUnit:"Unit 3 \xB7 Balanced Forces & Inertia"},yourNumbers:e=>{let t=e.num("Second ramp angle",30),a=e.num("Friction",.1),i=t*Math.PI/180,n=Math.max(0,1-a/Math.tan(Math.PI/6)),r=Math.sin(i)+a*Math.cos(i);return`h\u2080 = 1.00 m | s_up = h\u2080(1 \u2212 \u03BC cot30\xB0)/(sin\u03B8\u2082 + \u03BC cos\u03B8\u2082) = ${r>0?(n/r).toFixed(2):"\u221E"} m`},cutaway:"The widget is an ideal sliding puck, with no rotation. Friction opposes sliding on each slope and transfers mechanical energy into warmth.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Released on the left slope, the puck climbs the right slope toward its original height line.",act:e=>{e.setSlider("Friction",0),e.setSlider("Second ramp angle",25),e.clickBtn("Release")}},{title:"2. Close-up",caption:"2/5 Close-up: Lowering the right slope to 10\xB0 makes the puck travel much farther horizontally to reach the same height.",act:e=>{e.setSlider("Second ramp angle",10),e.clickBtn("Release")}},{title:"3. Cut-away",caption:"3/5 Cut-away: Why Galileo polished the parchment-lined channel to strip away friction.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Flatten the right ramp to 0\xB0 and the puck never reaches its starting height\u2014so with no friction it slides onward.",act:e=>{e.setSlider("Second ramp angle",0),e.clickBtn("Release")}},{title:"5. Your turn",caption:"5/5 Your turn: Test any ramp angle with or without friction.",cutaway:!1}],idealised:"The corner between the two ramps is smoothed so no kinetic energy is lost to a bounce at the bottom transition."},forces:{challenge:{prompt:"On the rough floor (100 N friction), balance or unbalance the two rope pulls until the net force to the right is exactly 150 N.",check:e=>{if(e.tab(0)!==1)return!1;let t=e.num("Pull to the right",0),a=e.num("Pull to the left",0);return t-a===250&&/Net force 150 N to the right/.test(e.readout())}},presets:[{name:"Tug-of-War Tie",prompt:"Equal 250 N pulls from rest on smooth floor.",state:{tabs:[0],sliders:{"Pull to the left":250,"Pull to the right":250},custom:{v:0,x:0}}},{name:"Cruising at Zero Net Force",prompt:"Moving at 4.0 m/s with equal 200 N pulls\u2014watch the water level!",state:{tabs:[0],sliders:{"Pull to the left":200,"Pull to the right":200},custom:{v:4,x:0,loadIdx:0}}},{name:"Mystery Box Weighing",prompt:"Pull the unknown ? kg crate and compute m = F_net / a.",state:{tabs:[0],sliders:{"Pull to the left":0,"Pull to the right":240},custom:{v:0,x:0,loadIdx:2,mysteryRevealed:!1}}}],mentorTips:{openPlay:"Let Kym get the cart moving, then set both pulls equal to 200 N\u2014watch the water glass stay dead flat!",misconception:"Thinking zero net force means the cart must stop (confusing net force with velocity instead of acceleration).",dinnerQuestion:"On a smooth Mumbai local train cruising steadily between stations, does a glass of water tilt forward, backward, or stay flat?",cambridgeUnit:"Unit 3 \xB7 Forces, Friction & Acceleration"},yourNumbers:e=>{let t=e.num("Pull to the left",200),a=e.num("Pull to the right",200);return`Applied pull = ${a} \u2212 ${t} = ${a-t} N. \u03A3F = applied pull + contact friction; sliding friction opposes velocity, while static friction balances up to 100 N at rest. See the readout for the current net force.`},cutaway:"Inside the floor contact: microscopic bumps (asperities) on the crate interlock with the floorboards up to the 100 N friction limit.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Equal pulls of 200 N left and right cancel to a net force of 0 N.",act:e=>{e.selectTab(0,0),e.setSlider("Pull to the left",200),e.setSlider("Pull to the right",200)}},{title:"2. Close-up",caption:"2/5 Close-up: Pulling harder to the right creates an unbalanced force and accelerates the crate.",act:e=>e.setSlider("Pull to the right",350)},{title:"3. Cut-away",caption:"3/5 Cut-away: Under a microscope, rough floor asperities push back against the sliding crate.",cutaway:!0,act:e=>e.selectTab(0,1)},{title:"4. Side-on trend",caption:"4/5 Trend: On the rough floor, pulls smaller than 100 N are matched completely by static friction.",act:e=>{e.setSlider("Pull to the left",0),e.setSlider("Pull to the right",80)}},{title:"5. Your turn",caption:"5/5 Your turn: Combine pulls and friction to hit the target net force.",cutaway:!1}],idealised:"Static and kinetic friction are set equal at 100 N here; in real wood-on-wood contact, static friction is slightly higher than sliding friction."},momentum_carts:{challenge:{prompt:"Choose a sticky inelastic collision and pick unequal cart masses so the joined pair finishes rolling faster than +1.1 m/s.",check:e=>{if(e.tab(0)!==1)return!1;let t=e.num("Mass of cart 1",.5),a=e.num("Mass of cart 2",.5),i=(t*2+a*-.5)/(t+a);return Math.abs(t-a)>=.05&&i>1.1}},presets:[{name:"Equal Elastic Swap",prompt:"Equal 0.50 kg carts bounce cleanly.",state:{tabs:[0],sliders:{"Mass of cart 1":.5,"Mass of cart 2":.5}}},{name:"Heavy Meets Light (Stick)",prompt:"Watch a massive cart capture a light cart.",state:{tabs:[1],sliders:{"Mass of cart 1":.8,"Mass of cart 2":.2}}}],mentorTips:{openPlay:"Try equal masses first, then make Cart 1 much heavier than Cart 2 in both Bounce and Stick modes.",misconception:"Assuming kinetic energy must stay conserved in sticky collisions just because total momentum does.",dinnerQuestion:"When two railway coaches couple and stick together, what disappears (KE) and what refuses to vanish (momentum)?",cambridgeUnit:"Unit 3 \xB7 Momentum & Collisions"},yourNumbers:e=>{let t=e.num("Mass of cart 1",.35),a=e.num("Mass of cart 2",.5),i=2,n=-.5,r=t*i+a*n,o=t+a;if(e.tab(0)===1)return`p = m\u2081(+2.00) + m\u2082(\u22120.50) = ${r.toFixed(2)} kg\xB7m/s; joined v = p/(m\u2081+m\u2082) = ${(r/o).toFixed(2)} m/s`;let s=((t-a)*i+2*a*n)/o,c=(2*t*i+(a-t)*n)/o;return`p = ${r.toFixed(2)} kg\xB7m/s; elastic result v\u2081\u2032 = ${s.toFixed(2)} m/s, v\u2082\u2032 = ${c.toFixed(2)} m/s`},cutaway:"Inside the bumper: spring steel stores \xBDkx\xB2 during an elastic bounce and returns it, whereas Velcro hooks trap the carts together and turn part of KE into warmth.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Equal-mass carts in an elastic bounce swap velocities completely.",act:e=>{e.selectTab(0,0),e.setSlider("Mass of cart 1",.5),e.setSlider("Mass of cart 2",.5)}},{title:"2. Close-up",caption:"2/5 Close-up: A heavy cart hitting a light cart keeps moving forward while kicking the light cart ahead faster.",act:e=>{e.setSlider("Mass of cart 1",.8),e.setSlider("Mass of cart 2",.2)}},{title:"3. Cut-away",caption:"3/5 Cut-away: Inside the spring vs Velcro bumpers during the millisecond of impact.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Even when the carts stick together and lose kinetic energy, total momentum p\u2081 + p\u2082 never changes.",act:e=>e.selectTab(0,1)},{title:"5. Your turn",caption:"5/5 Your turn: Adjust both cart masses and compare elastic vs sticky collisions.",cutaway:!1}],idealised:"Track wheel friction and air drag are set to zero so total horizontal momentum is strictly conserved."},whirl:{challenge:{prompt:"Raise the whirling speed, then compare the floor view and the ball\u2019s-seat frame right before and after releasing the string\u2014which way does the released ball actually travel?",check:e=>e.tab(0)===1&&Math.abs(e.num("Speed",2)-3.5)<.1},presets:[{name:"Floor Reference Frame",prompt:"Watch real inward tension perpendicular to tangent velocity.",state:{tabs:[0],sliders:{Speed:2}}},{name:"Rotating Seat View",prompt:"See why a turning observer feels an apparent outward throw.",state:{tabs:[1],sliders:{Speed:3.5}}}],mentorTips:{openPlay:"Let Kym predict which straight direction the ball takes if snipped at top-dead-centre.",misconception:'Thinking a released object spirals outward due to "centrifugal force" instead of moving straight along the tangent.',dinnerQuestion:'On a rainy Dadar Flyover turn, do groceries slide "outward" or keep trying to go straight while the car curves underneath them?',cambridgeUnit:"Unit 4 \xB7 Circular Motion & Reference Frames"},yourNumbers:e=>{if(/Released|No inward pull/.test(e.readout()))return"After release: real string tension T = 0 N; inertial velocity remains constant.";let t=e.num("Speed",2),a=1,i=.2,n=t*t/a,r=i*n;return`a_c = v\xB2 \xF7 r = ${t.toFixed(1)}\xB2 \xF7 ${a.toFixed(2)} = ${n.toFixed(2)} m/s\xB2  |  string tension T = m a_c = ${r.toFixed(2)} N`},cutaway:"Inside the taut string: fibres transmit the inward tension force T = mv\xB2/r; the instant the clip opens, T drops to 0 N.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: From the floor, the string pulls purely inward while the velocity points along the tangent.",act:e=>{e.selectTab(0,0),e.setSlider("Speed",2)}},{title:"2. Close-up",caption:"2/5 Close-up: Doubling the speed quadruples the inward tension needed to bend the path.",act:e=>e.setSlider("Speed",3.5)},{title:"3. Cut-away",caption:"3/5 Cut-away: The string tension vanishes the instant you let go\u2014there is no outward force pushing the ball.",cutaway:!0,act:e=>e.clickBtn("Release")},{title:"4. Side-on trend",caption:"4/5 Trend: Seen from the rotating seat, the straight tangent path looks like it curves outward.",act:e=>e.selectTab(0,1)},{title:"5. Your turn",caption:"5/5 Your turn: Release the ball at any point and compare both frames of reference.",cutaway:!1}],idealised:"The ball whirls on a frictionless horizontal table so gravity does not tilt the string downward into a cone."},cannon3d:{challenge:{prompt:"Discover the horizontal launch speed that puts Newton\u2019s cannonball into a steady circular orbit around Earth\u2014neither crashing nor escaping.",check:e=>{let t=e.num("Launch speed",4);return t>=7.8&&t<=8.1}},presets:[{name:"Sub-orbital Arc",prompt:"Slow throw falls back to Earth at 4.0 km/s.",state:{sliders:{"Launch speed":4}}},{name:"Elliptical Orbit",prompt:"Launch at 9.5 km/s to stretch the orbit.",state:{sliders:{"Launch speed":9.5}}}],mentorTips:{openPlay:"Fire once at low speed, once slightly faster, and ask why Earth\u2019s curved surface changes the landing spot.",misconception:"Believing astronauts float in orbit because Earth\u2019s gravity suddenly switches off above the atmosphere.",dinnerQuestion:"If gravity still pulls nearly 90% as strongly at ISS altitude as here in Mumbai, why doesn\u2019t the space station crash into Earth?",cambridgeUnit:"Unit 3 \xB7 Gravity & Orbital Free Fall"},yourNumbers:e=>{let t=e.num("Launch speed",4),a=6381,i=3986e11/6381e3**2,n=t*t/a*1e3;return`v\u2080 = ${t.toFixed(1)} km/s  |  v\xB2 \xF7 r = ${n.toFixed(2)} m/s\xB2 vs gravity g(h) = ${i.toFixed(2)} m/s\xB2 (circular at 7.9 km/s)`},cutaway:"Inside Newton\u2019s gravitational field: gravity pulls toward Earth\u2019s centre at every point; at 7.9 km/s the ground curves away by 4.9 m every second\u2014matching the fall.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: At 4.0 km/s the cannonball arcs partway around the globe and lands.",act:e=>{e.setSlider("Launch speed",4),e.clickBtn("Fire")}},{title:"2. Close-up",caption:"2/5 Close-up: At 7.9 km/s the ball falls continuously around the curving Earth in a circular orbit.",act:e=>{e.setSlider("Launch speed",7.9),e.clickBtn("Fire")}},{title:"3. Cut-away",caption:"3/5 Cut-away: Gravity never turns off in orbit\u2014it is the inward centripetal force bending the path.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: At 9.5 km/s the orbit stretches into an ellipse; above 11.2 km/s it escapes.",act:e=>{e.setSlider("Launch speed",9.5),e.clickBtn("Fire")}},{title:"5. Your turn",caption:"5/5 Your turn: Drag the 3D globe and test any launch speed.",cutaway:!1}],idealised:"Air is omitted even at the 10 km launch altitude. Reaching the 4.2 Earth-radius drawing horizon is a display limit; the sign of orbital energy decides bound motion or escape."},tides:{challenge:{prompt:"Advance the lunar month until the Moon and Sun pull at right angles, creating the smallest tidal range (a neap tide).",check:e=>{let a=e.num("Time in lunar month",0)/24;return Math.abs(a-7.4)<=.8||Math.abs(a-22.1)<=.8}},presets:[{name:"Spring Tide Alignment",prompt:"New Moon alignment gives maximum combined bulge.",state:{sliders:{"Time in lunar month":0}}},{name:"Full Month Cycle",prompt:"Check the Moon 14.8 days into the cycle.",state:{sliders:{"Time in lunar month":355}}}],mentorTips:{openPlay:"Notice there are TWO water bulges on opposite sides of Earth before advancing time.",misconception:"Thinking tides only happen on the side facing the Moon, ignoring the far-side differential bulge.",dinnerQuestion:"Why does Mumbai get high tide twice every ~25 hours instead of only once when the Moon passes overhead?",cambridgeUnit:"Unit 3 \xB7 Differential Gravity"},yourNumbers:e=>{let a=e.num("Time in lunar month",0)/24,i=a*12.19*Math.PI/180,n=/Sun’s bulges turned off/.test(e.readout())?0:.46,r=Math.sqrt(1+n*n+2*n*Math.cos(2*i));return`Day ${a.toFixed(1)} of 29.5  |  \u0394F_tide \u221D M \xF7 r\xB3 (Sun = ${Math.round(n*100)}% of Moon)  \u2192  combined bulge = ${(r*100).toFixed(0)}% of lunar average`},cutaway:"Inside the tidal differential: the Moon pulls the near-side ocean ~3% harder than Earth\u2019s rigid core, and the core ~3% harder than the far-side ocean, stretching water both ways.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: At new moon (Day 0), lunar and solar bulges align for high spring tides.",act:e=>e.setSlider("Time in lunar month",0)},{title:"2. Close-up",caption:"2/5 Close-up: Earth spins through both bulges every 24 h 50 min, giving two high tides a day.",act:e=>e.setSlider("Time in lunar month",12)},{title:"3. Cut-away",caption:"3/5 Cut-away: Why there is a bulge on the side opposite the Moon\u2014differential gravity across Earth\u2019s diameter.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: At quarter moon (Day 7.4), the Sun partly cancels the Moon\u2019s bulge (neap tide).",act:e=>e.setSlider("Time in lunar month",178)},{title:"5. Your turn",caption:"5/5 Your turn: Scrub through the month or toggle the Sun\u2019s 46% bulge.",cutaway:!1}],idealised:"The Earth is drawn covered by a uniform deep ocean without continents or shallow coastal bays that amplify real tides."},pressuretank:{challenge:{prompt:"Switch to the densest liquid in the tray and fill the tank until gauge pressure slightly exceeds standard atmospheric pressure (101.3 kPa).",check:e=>e.tab(0)===2&&e.num("Depth of liquid",1)>=.76&&e.num("Depth of liquid",1)<=.9},presets:[{name:"Deep Fresh Water",prompt:"2.0 m water column to test \u0394p = \u03C1gh.",state:{tabs:[0],sliders:{"Depth of liquid":2}}},{name:"Sea Water Column",prompt:"Compare slightly denser salty sea water at 1.5 m.",state:{tabs:[1],sliders:{"Depth of liquid":1.5}}}],mentorTips:{openPlay:"Compare water depth at 1.0 m vs 2.0 m first, then switch liquids.",misconception:"Thinking wider tanks create higher pressure at the bottom than narrow columns of the same depth.",dinnerQuestion:"Why did Torricelli only need a 76 cm column of mercury to balance 10 metres of water and the entire sky above Mumbai?",cambridgeUnit:"Unit 3 \xB7 Pressure in Liquids & Gases"},yourNumbers:e=>{let t=e.num("Depth of liquid",1),i=[1e3,1025,13600][e.tab(0)]||1e3,n=i*9.8*t/1e3;return`\u0394p = \u03C1gh/1000 = ${i} \xD7 9.8 \xD7 ${t.toFixed(1)} / 1000 = ${n.toFixed(1)} kPa  (+ 101.3 kPa air = ${(n+101.3).toFixed(1)} kPa total)`},cutaway:"Inside the fluid column: every horizontal layer supports the weight of all the liquid and air stacked above it, pushing equally in all directions at that depth.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Pressure increases linearly with depth, regardless of the width of the tank.",act:e=>{e.selectTab(0,0),e.setSlider("Depth of liquid",1)}},{title:"2. Close-up",caption:"2/5 Close-up: Doubling the water depth from 1.0 m to 2.0 m doubles the liquid gauge pressure.",act:e=>e.setSlider("Depth of liquid",2)},{title:"3. Cut-away",caption:"3/5 Cut-away: Molecular collisions transmit the weight of the overlying column in every direction.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Mercury is 13.6 times denser than water, so just 0.8 m produces over 100 kPa.",act:e=>{e.selectTab(0,2),e.setSlider("Depth of liquid",.8)}},{title:"5. Your turn",caption:"5/5 Your turn: Compare liquids and toggle atmospheric pressure.",cutaway:!1}],idealised:"The liquid is treated as strictly incompressible (constant density \u03C1 at all depths)."},buoyancy:{challenge:{prompt:"Test solid steel (7,800 kg/m\xB3) in water so it sinks, then discover how reshaping the exact same mass into a hollow hull makes it float.",check:e=>e.num("Block density",600)>=7e3&&/floats/i.test(e.readout())},presets:[{name:"Floating Wood (600)",prompt:"Notice how submerged percentage matches density ratio.",state:{tabs:[0],sliders:{"Block density":600}}},{name:"Sink Solid Iron",prompt:"Drop solid steel into fresh water and inspect upthrust vs weight.",state:{tabs:[0],sliders:{"Block density":7800}}},{name:"Mystery ? Block",prompt:"Measure displaced waterline and submerged fraction to deduce ? density.",state:{tabs:[0],custom:{mysteryMode:!0,mysteryRevealed:!1,liqIdx:0,hollow:!1}}}],mentorTips:{openPlay:"Ask Kym to predict what fraction of a 600 kg/m\xB3 wood block sits underwater before running it.",misconception:"Confusing material density with total mass when deciding why huge steel cargo ships float near Nhava Sheva.",dinnerQuestion:"A steel nail sinks instantly in a bucket, yet a 50,000-ton steel ship floats effortlessly\u2014what changed?",cambridgeUnit:"Unit 3 \xB7 Density, Upthrust & Floating"},yourNumbers:e=>{let t=[1e3,1025,13600][e.tab(0)]||1e3,a=e.readout();if(/Mystery\s*\?\s*block/i.test(a))return`Mystery ? block in liquid \u03C1 = ${t} kg/m\xB3: at calm floating equilibrium, \u03C1_block = \u03C1_fluid \xD7 (submerged fraction). Check the submerged % gauge!`;let i=/\b650\s*kg\/m³/.test(a)?650:e.num("Block density",920),n=/Hollowed out:/.test(a),r=n?i/10:i,o=n?1:.1,s=i*.1,c=Math.min(100,100*r/t);return`Same mass = ${s.toFixed(1)} kg; W = ${(s*9.8).toFixed(1)} N. Body volume = ${o.toFixed(1)} m\xB3; \u03C1_avg = ${r.toFixed(0)} kg/m\xB3. ${r>t?"Sinks; floor support supplies W \u2212 buoyancy.":`Floating equilibrium \u2248 ${c.toFixed(1)}% submerged.`}`},cutaway:"Inside the pressure difference: water is deeper at the bottom face of the block than at the top face, so upward pressure force exceeds downward pressure force by \u03C1_liq V g.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: A wood block (600 kg/m\xB3) floats with 60% of its volume below the waterline.",act:e=>{e.selectTab(0,0),e.setSlider("Block density",600)}},{title:"2. Close-up",caption:"2/5 Close-up: Solid steel (7,800 kg/m\xB3) weighs more than an equal volume of water, so it sinks.",act:e=>e.setSlider("Block density",7800)},{title:"3. Cut-away",caption:"3/5 Cut-away: Upthrust comes from higher fluid pressure on the deeper bottom face of the hull.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Hollowing out the steel block lowers its average density below 1,000 kg/m\xB3 so it floats like a ship.",act:e=>e.clickBtn("Hollow")},{title:"5. Your turn",caption:"5/5 Your turn: Test any block density across fresh water, sea water, and mercury.",cutaway:!1}],idealised:"Surface tension at the waterline and viscous water drag are simplified for clarity."},energystores:{challenge:{prompt:"Inspect the bouncing tennis ball and pause right at maximum compression at the bottom of the bounce where the elastic store peaks.",check:e=>e.tab(0)===0&&e.num("Transfer progress",0)>=1.35&&e.num("Transfer progress",0)<=1.65},presets:[{name:"Bounce Compression",prompt:"Watch gravitational \u2192 kinetic \u2192 elastic store transfer.",state:{tabs:[0],sliders:{"Transfer progress":1.5}}},{name:"Solar Hydrogen Fusion",prompt:"Contrast huge cosmic energy scales against daily mechanical stores.",state:{tabs:[3],sliders:{"Transfer progress":2}}}],mentorTips:{openPlay:"Track whether the SUM of all glowing jars ever drops when transferring between stores.",misconception:'Thinking energy "changes into work" as if work were a fifth jar rather than a pathway tube.',dinnerQuestion:"At Sivaji Park cricket net practice, what happens to the bat\u2019s energy a millisecond after hitting a six\u2014where does every last joule end up?",cambridgeUnit:"Unit 3 \xB7 Energy Stores & Pathways"},yourNumbers:e=>`\u03A3E_stores = const  |  transfer = ${Math.round(e.num("Transfer progress",0)/3*100)}%  |  auto-scaled jar capacity \u2208 {1, 2, 5} \xD7 10\u207F J`,cutaway:"Inside the pathway tubes: mechanical work is an ordered force push, electrical work is drift of electrons, heating is random molecular jiggling, and radiation is electromagnetic waves.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Energy sits in glowing hatched jars and pours through pathway tubes.",act:e=>{e.selectTab(0,0),e.setSlider("Transfer progress",0)}},{title:"2. Close-up",caption:"2/5 Close-up: At impact, gravitational and kinetic stores empty into the elastic jar and thermal jar.",act:e=>e.setSlider("Transfer progress",1.5)},{title:"3. Cut-away",caption:"3/5 Cut-away: Each store has a unique monochrome hatch and each pathway has its own flow shader.",cutaway:!0,act:e=>e.selectTab(0,1)},{title:"4. Side-on trend",caption:"4/5 Trend: In one second of sunshine, the Sun\u2019s nuclear jar (3.83 \xD7 10\xB2\u2076 J) overflows any earthly scale.",act:e=>{e.selectTab(0,3),e.setSlider("Transfer progress",2.2)}},{title:"5. Your turn",caption:"5/5 Your turn: Scrub through all 4 scenarios or view all 8 hatched stores.",cutaway:!1}],idealised:"Each jar groups microscopic kinetic and potential energies into a single macroscopic store label."},energytrack:{challenge:{prompt:"With friction set to 0.10, discover the lowest release height that still carries the marble cleanly over the 0.80 m bump.",check:e=>Math.abs(e.num("Friction",0)-.1)<.015&&Math.abs(e.num("Release height",1)-1.1)<.05},presets:[{name:"Frictionless Conservation",prompt:"Zero friction at 1.0 m: watch PE and KE trade cleanly.",state:{tabs:[0,0],sliders:{Friction:0,"Release height":1},custom:{hRef:0,gIdx:0}}},{name:"Barely Clears the Bump",prompt:"With \u03BC = 0.10, test whether 1.0 m is enough or needs higher.",state:{tabs:[0,2],sliders:{Friction:.1,"Release height":1},custom:{hRef:0,gIdx:0}}},{name:"Moon Gravity Drop",prompt:"Compare speeds and total joules on the Moon (g = 1.6 m/s\xB2).",state:{tabs:[0,0],sliders:{Friction:0,"Release height":1.2},custom:{hRef:0,gIdx:1}}}],mentorTips:{openPlay:'Drag the marble directly on the track and turn on "Pie on bead" before adjusting friction.',misconception:'Thinking a heavier steel marble rolls faster down the track than a lighter glass marble, or believing energy is "used up" by friction.',dinnerQuestion:"If a roller coaster starts at 30 m high without an engine, can any later hill ever be 32 m high? What happens when friction warms the rails?",cambridgeUnit:"Unit 3 \xB7 Conservation of Energy"},yourNumbers:e=>{let t=e.num("Release height",1),a=e.num("Friction",0),i=e.tab(0)===1?.06:.02,n=[9.8,1.6,24.8][e.tab(2)]??9.8,r=i*n*t;return`E_total = m g h\u2080 = ${i.toFixed(3)} \xD7 ${n.toFixed(1)} \xD7 ${t.toFixed(2)} = ${r.toFixed(3)} J  |  E_p + E_k + E_therm = ${r.toFixed(3)} J (\u03BC = ${a.toFixed(2)})`},cutaway:"Inside the sliding bead and track: friction converts ordered motion into random lattice vibrations (thermal store) without changing the total joules.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Height store and motion store trade back and forth while the total bar never changes.",act:e=>{e.setSlider("Friction",0),e.setSlider("Release height",1)}},{title:"2. Close-up",caption:"2/5 Close-up: Released from 0.7 m, the marble lacks the joules to reach the 0.8 m bump and slides back.",act:e=>e.setSlider("Release height",.7)},{title:"3. Cut-away",caption:"3/5 Cut-away: Switching from bars to glowing hatched jars shows height, motion and warmth energy stores; friction transfers energy into internal motion.",cutaway:!0,act:e=>{e.selectTab(1,1),e.setSlider("Release height",1.2)}},{title:"4. Side-on trend",caption:"4/5 Trend: With friction on, each pass fills the warmth store until the marble settles in the dip.",act:e=>e.setSlider("Friction",.1)},{title:"5. Your turn",caption:"5/5 Your turn: Solve the 0.80 m bump challenge with friction at 0.10.",cutaway:!1,act:e=>e.selectTab(1,0)}],idealised:"The marble slides without rotational inertia (\xBDI\u03C9\xB2), so all its motion energy is translational \xBDmv\xB2."},conduction:{challenge:{prompt:"Compare steel, wood, and aluminium with a 37 \xB0C hand; every surface starts at the same 30 \xB0C room temperature.",check:e=>Math.abs(e.num("Hand temperature",35)-37)<.5&&e.tab(0)>0},presets:[{name:"Steel Spoon",prompt:"Steady metallic heat drain from fingertips.",state:{tabs:[0],sliders:{"Hand temperature":37}}},{name:"Teak Wood Bench",prompt:"Surface heats rapidly and halts heat flow.",state:{tabs:[1],sliders:{"Hand temperature":37}}}],mentorTips:{openPlay:"Ask Kym whether metal spoons in the kitchen are actually colder than wooden ladles on a 30 \xB0C Mumbai counter.",misconception:"Believing metals have an inherently lower temperature than insulators in the same room.",dinnerQuestion:"Why does brass railing on the Bandra\u2013Worli promenade feel cooler at dawn than a painted wooden bench right beside it?",cambridgeUnit:"Unit 5 \xB7 Thermal Conduction & Rate"},yourNumbers:e=>{let t=e.num("Hand temperature",35),a=e.tab(0),i=[14,.12,220][a];return`${["Steel","Wood","Aluminium"][a]}: k = ${i} W/(m\xB7K). Initial \u0394T = ${t} \u2212 30 = ${(t-30).toFixed(1)} \xB0C. The relative flow gauge changes as the contact layers warm.`},cutaway:"Mobile electrons help transfer energy in metals. Wood is a much poorer conductor. This lumped-layer model shows contact transfer without calibrating a material\u2019s cooling time.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: All three surfaces start at 30 \xB0C, cooler than the 35 \xB0C hand.",act:e=>{e.selectTab(0,0),e.setSlider("Hand temperature",35)}},{title:"2. Close-up",caption:"2/5 Close-up: Touching steel transfers energy away from the warmer skin into the surface layers.",act:e=>e.selectTab(0,0)},{title:"3. Cut-away",caption:"3/5 Cut-away: Compare local energy transport through aluminium with wood; the sites themselves remain near their places.",cutaway:!0,act:e=>e.selectTab(0,2)},{title:"4. Side-on trend",caption:"4/5 Trend: On wood, heat stays right at the surface so skin and wood quickly reach nearly the same temperature.",act:e=>e.setSlider("Hand temperature",37)},{title:"5. Your turn",caption:"5/5 Your turn: Switch materials and adjust hand temperature.",cutaway:!1}],idealised:"Heat flow is modelled in one dimension along the bar without convective heat loss to the surrounding room air."},ripple:{challenge:{prompt:"Move from one dipping finger to two synchronised fingers dipping briskly\u2014where do calm nodal corridors appear between oscillating crests?",check:e=>e.tab(0)===1&&Math.abs(e.num("Rhythm",0)-2)<=.1},presets:[{name:"Single Circular Ripples",prompt:"Measure \u03BB spacing from one steady source.",state:{tabs:[0],sliders:{Rhythm:1.5}}},{name:"Two-Finger Interference",prompt:"Locate calm cancellation rays between two sources.",state:{tabs:[1],sliders:{Rhythm:2}}}],mentorTips:{openPlay:"Watch one bright float dot carefully\u2014does it swim across the tank or bob up and down in place?",misconception:"Assuming water moves outward across the tank together with the expanding wave crests.",dinnerQuestion:"When two speedboats pass near Gateway of India, why do calm flat streaks cut diagonally across the choppy wake?",cambridgeUnit:"Unit 6 \xB7 Wave Superposition & Ripples"},yourNumbers:e=>{let t=e.num("Rhythm",0),i=t>0?(3/t).toFixed(1):"pulse";return t>0?`Drawing speed v = f \u03BB = 3.0 cm/s  |  f = ${t.toFixed(1)} Hz  \u2192  \u03BB = 3.0 \xF7 ${t.toFixed(1)} = ${i} cm`:"Single pulse: circular wavefronts expand at the slowed drawing speed v = 3.0 cm/s"},cutaway:"Inside the water surface: water parcels move in tiny vertical circles as the crest passes\u2014the wave travels across the tank while the water stays in place.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: A single tap sends out circular ripples at constant wave speed.",act:e=>{e.selectTab(0,0),e.setSlider("Rhythm",0)}},{title:"2. Close-up",caption:"2/5 Close-up: Steady dipping at 1.5 Hz spaces the circular crests one wavelength apart.",act:e=>e.setSlider("Rhythm",1.5)},{title:"3. Cut-away",caption:"3/5 Cut-away: Water molecules orbit locally in place while energy radiates outward.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Two fingers dipping in step create nodal lanes where crest meets trough.",act:e=>{e.selectTab(0,1),e.setSlider("Rhythm",2)}},{title:"5. Your turn",caption:"5/5 Your turn: Tap anywhere on the water tank or change the rhythm.",cutaway:!1}],idealised:"The tank walls are non-reflecting so outgoing ripples are not muddied by echoes from the edges."},scope:{challenge:{prompt:"View waveform and frequency spectrum together, then hum a steady vowel or pluck a note\u2014how does changing pitch move the frequency peaks?",check:e=>e.tab(0)===1},presets:[{name:"Waveform Trace",prompt:"Inspect cycle period T in milliseconds.",state:{tabs:[0]}},{name:"Waveform + FFT Spectrum",prompt:"Separate pure tone peaks from rich overtones.",state:{tabs:[1]}}],mentorTips:{openPlay:"Hum softly then loudly at the same pitch\u2014check what changes on the trace (height vs spacing).",misconception:"Confusing louder volume (amplitude) with higher pitch (frequency) on a scope trace.",dinnerQuestion:"Why does a tanpura string and a flute playing the exact same Sa (240 Hz) produce completely different shapes on an oscilloscope?",cambridgeUnit:"Unit 6 \xB7 Sound Waveforms & Spectra"},yourNumbers:e=>`f = 1 \xF7 T  |  v_sound \u2248 343 m/s at 20 \xB0C  |  view: ${e.tab(0)===1?"Time waveform + FFT spectrum":"Time waveform y(t)"}`,cutaway:"In a capacitive microphone, sound bends a flexible diaphragm and changes its capacitance; the electronics turn that change into a signal. The plot is an uncalibrated signal, not pressure in pascals.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: The oscilloscope plots relative microphone signal against time in milliseconds; the initial trace is a simulated reference tone.",act:e=>e.selectTab(0,0)},{title:"2. Close-up",caption:"2/5 Close-up: Higher pitch packs more wave cycles into the same millisecond window."},{title:"3. Cut-away",caption:"3/5 Cut-away: How a condenser microphone converts air pressure ripples into voltage.",cutaway:!0},{title:"4. Side-on trend",caption:'4/5 Trend: The "Both" view separates a complex wave into its pure harmonic frequencies.',act:e=>e.selectTab(0,1)},{title:"5. Your turn",caption:"5/5 Your turn: Freeze the trace or test your own voice with the microphone button.",cutaway:!1}],idealised:"Without the microphone active, the scope displays a clean synthetic reference tone free of room background noise."},harmonics:{challenge:{prompt:"Enrich upper overtones and compare the plain circular drumhead with the loaded Tabla\u2014why does the tabla\u2019s note sing at a crisp musical pitch?",check:e=>e.tab(0)===2&&Math.abs(e.num("Upper overtones",.5)-.6)<=.12},presets:[{name:"Plain Circular Drum",prompt:"Listen to non-integer membrane modes (1 : 1.59 : 2.14).",state:{tabs:[1],sliders:{"Upper overtones":.5}}},{name:"Raman Tabla (Syahi)",prompt:"Centre patch aligns modes into integer harmonics.",state:{tabs:[2],sliders:{"Upper overtones":.6}}}],mentorTips:{openPlay:"Compare the frequency ladder bars for Plain drum vs Tabla before turning up upper overtones.",misconception:"Thinking any stretched drum automatically produces neat integer multiples like a violin string.",dinnerQuestion:"Why does a tabla with its black central syahi spot sound pitched like a note, whereas a bass drum sounds like a thud?",cambridgeUnit:"Unit 6 \xB7 Sound, Pitch & Harmonics"},yourNumbers:e=>{let t=["String (1 : 2 : 3 : 4)","Plain drum (1 : 1.59 : 2.14)","Tabla with syahi (1 : 2 : 3)"][e.tab(0)]||"String",a=Math.round(e.num("Upper overtones",.5)*100);return`${e.tab(0)===1?"Non-integer drum partial ratios":"Idealised harmonic ratios f_n \u2248 n f\u2080"}  |  ${t}  |  overtone mix = ${a}%`},cutaway:"Inside the tabla head: C. V. Raman showed that the iron-paste syahi mass-loads the centre of the membrane so its modes shift into integer harmonic ratios 1 : 2 : 3 : 4 : 5.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: A plucked string vibrates in standing-wave loops with ratios 1 : 2 : 3 : 4.",act:e=>{e.selectTab(0,0),e.setSlider("Upper overtones",.5)}},{title:"2. Close-up",caption:"2/5 Close-up: A plain circular drumhead has non-integer modes (1.59\xD7, 2.14\xD7), sounding like a thud.",act:e=>e.selectTab(0,1)},{title:"3. Cut-away",caption:"3/5 Cut-away: How the black syahi patch on a tabla retunes the membrane modes into singing harmonics.",cutaway:!0,act:e=>e.selectTab(0,2)},{title:"4. Side-on trend",caption:"4/5 Trend: Raising the overtone slider enriches the timbre without changing the fundamental pitch.",act:e=>e.setSlider("Upper overtones",.6)},{title:"5. Your turn",caption:"5/5 Your turn: Compare String, Plain drum, and Tabla and tap Play to hear them.",cutaway:!1}],idealised:"Six partials are summed. The small drum views illustrate mode families; a real loaded tabla needs a full membrane model and has many higher modes."},doppler:{challenge:{prompt:"Drive a fast express train past a station listener blowing a high brass horn\u2014what changes between approach and recession, wave speed or wavefront spacing?",check:e=>Math.abs(e.num("Train speed",60)-90)<=5&&Math.abs(e.num("Horn note",330)-400)<=10},presets:[{name:"Stationary Horn",prompt:"At 0 km/h wavefront circles stay symmetric.",state:{sliders:{"Train speed":0,"Horn note":330}}},{name:"Mumbai Express 90 km/h",prompt:"Observe bunched crests ahead and stretched crests behind.",state:{sliders:{"Train speed":90,"Horn note":400}}}],mentorTips:{openPlay:"Watch the wavefront spacing ahead vs behind the engine as speed rises from 0.",misconception:"Thinking the air pushes sound faster ahead of a train (actually wave speed c stays constant; wavelength \u03BB bunches up).",dinnerQuestion:"As a Western Line fast local races past Bandra platform blowing its horn, does the driver inside the cab hear the pitch drop too?",cambridgeUnit:"Unit 6 \xB7 Sound Waves & Frequency"},yourNumbers:e=>{let a=e.num("Train speed",60)/3.6,i=e.num("Horn note",330),n=348.7,r=i*n/(n-a),o=i*n/(n+a);return`f_obs = f\u2080 \xD7 c \xF7 (c \u2213 v_s)  |  v_s = ${a.toFixed(1)} m/s  \u2192  ahead ${r.toFixed(0)} Hz, behind ${o.toFixed(0)} Hz (\u0394f = ${(r-o).toFixed(0)} Hz)`},cutaway:"Inside the wavefront bunching: each sound crest leaves the horn and expands at 348.7 m/s in 30 \xB0C air, but the moving horn emits the next crest closer to the previous one.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: When the train stands still (0 km/h), sound circles are concentric and everyone hears the same pitch.",act:e=>{e.setSlider("Train speed",0),e.setSlider("Horn note",330)}},{title:"2. Close-up",caption:"2/5 Close-up: At 60 km/h, crests bunch up ahead of the engine and stretch out behind it.",act:e=>e.setSlider("Train speed",60)},{title:"3. Cut-away",caption:"3/5 Cut-away: The air itself does not speed up\u2014only the spacing \u03BB between successive crests changes.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: At 90 km/h with a 400 Hz horn, the far-approach to far-recession pitch change is about 58 Hz, or 2.5 semitones.",act:e=>{e.setSlider("Train speed",90),e.setSlider("Horn note",400)}},{title:"5. Your turn",caption:"5/5 Your turn: Adjust speed and horn frequency, or press Sound the horn.",cutaway:!1}],idealised:"The listener stands close to the track so the cosine angle factor approaches \xB11 except right at the moment of passing."},mirror:{challenge:{prompt:"Examine full-body reflection as you step farther back from the mirror\u2014does stepping back reveal more of your body, or does a half-height mirror always work?",check:e=>e.tab(0)===1&&Math.abs(e.num("Distance from mirror",70)-120)<=5},presets:[{name:"Point Ray Diagram",prompt:"See equal angles \u03B8_i = \u03B8_r from one object point.",state:{tabs:[0],sliders:{"Distance from mirror":70}}},{name:"Whole Body Half-Mirror",prompt:"Compare standing close vs 120 cm back.",state:{tabs:[1],sliders:{"Distance from mirror":120}}}],mentorTips:{openPlay:"Guess first whether walking back from the wardrobe mirror shows more or the exact same fraction of your body.",misconception:"Believing stepping farther back from a flat wall mirror lets you see down to your shoes.",dinnerQuestion:"How tall must a corridor wall mirror at home be for a 1.6 m person to see both hair and slippers at once?",cambridgeUnit:"Unit 7 \xB7 Reflection & Plane Mirrors"},yourNumbers:e=>{let t=e.num("Distance from mirror",70);return`\u03B8_i = \u03B8_r  |  object distance d_o = ${t} cm = image distance d_i = ${t} cm behind glass (total separation = ${2*t} cm)`},cutaway:"Inside the silvered glass: incoming photons reflect off the thin aluminium/silver backing at \u03B8_i = \u03B8_r; your visual cortex projects diverging rays straight backward to a virtual image.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Every ray from the object bounces off the mirror at an angle equal to its arrival angle.",act:e=>{e.selectTab(0,0),e.setSlider("Distance from mirror",70)}},{title:"2. Close-up",caption:"2/5 Close-up: Extended straight back behind the mirror, all reflected rays meet at one virtual image point.",act:e=>e.setSlider("Distance from mirror",100)},{title:"3. Cut-away",caption:"3/5 Cut-away: Why no light actually goes behind the wall\u2014virtual rays are sightlines traced by your eye.",cutaway:!0},{title:"4. Side-on trend",caption:'4/5 Trend: In "Whole body" mode, similar triangles guarantee that a mirror half your height shows your full body at any distance.',act:e=>{e.selectTab(0,1),e.setSlider("Distance from mirror",120)}},{title:"5. Your turn",caption:"5/5 Your turn: Walk closer or farther and toggle the traced-back rays.",cutaway:!1}],idealised:"The mirror is treated as a front-surface reflector, ignoring the weak second reflection from the front face of household glass."},refraction:{challenge:{prompt:"Choose the highest-index material, send light from material into air, and discover the steep angle where 100% of light traps inside (Total Internal Reflection).",check:e=>e.tab(0)===2&&e.num("Arriving angle",35)>=25&&/total internal reflection/i.test(e.readout())},presets:[{name:"Air into Water",prompt:"Ray slows down and bends toward the normal.",state:{tabs:[0],sliders:{"Arriving angle":45}}},{name:"Glass Critical Threshold",prompt:"Compare glass-to-air around 40\u201345\xB0.",state:{tabs:[1],sliders:{"Arriving angle":42}}}],mentorTips:{openPlay:"Always ask whether the ray bends toward or away from the 90\xB0 normal first.",misconception:"Measuring angles from the flat surface instead of the normal line, or expecting TIR when entering from air into glass.",dinnerQuestion:"Why does a diamond sparkle intensely while a piece of plain glass of the same cut looks dull?",cambridgeUnit:"Unit 6 \xB7 Refraction & Critical Angle"},yourNumbers:e=>{let t=e.num("Arriving angle",35),i=[1.333,1.52,2.419][e.tab(0)]||1.333,n=/^(Water|Glass|Diamond) to air/i.test(e.readout()),r=n?i:1,o=n?1:i,s=r/o*Math.sin(t*Math.PI/180);if(s>1){let h=(Math.asin(o/r)*180/Math.PI).toFixed(1);return`n\u2081 sin \u03B8\u2081 = ${r.toFixed(3)} \xD7 sin(${t}\xB0) > 1.000  \u2192  Total Internal Reflection! (\u03B8_c = ${h}\xB0)`}let c=(Math.asin(s)*180/Math.PI).toFixed(1);return`n\u2081 sin \u03B8\u2081 = n\u2082 sin \u03B8\u2082  \u2192  ${r.toFixed(2)} sin(${t}\xB0) = ${o.toFixed(2)} sin(${c}\xB0)`},cutaway:"Inside the wavefront boundary: light slows down to c/n inside glass or diamond, so the edge of each wavefront that enters first falls behind and pivots the beam.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Light entering water (n = 1.333) slows down and bends toward the normal.",act:e=>{e.selectTab(0,0),e.setSlider("Arriving angle",45)}},{title:"2. Close-up",caption:"2/5 Close-up: Diamond (n = 2.419) slows light to 41% of c, bending the ray sharply.",act:e=>e.selectTab(0,2)},{title:"3. Cut-away",caption:"3/5 Cut-away: Wavefront crests march closer together in the slower medium, pivoting the ray direction.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Going from diamond into air above the 24.4\xB0 critical angle traps 100% of the light inside.",act:e=>{e.clickBtn("Direction"),e.setSlider("Arriving angle",30)}},{title:"5. Your turn",caption:"5/5 Your turn: Explore angles, materials, and critical angles.",cutaway:!1}],idealised:"The beam is monochromatic; real white light splits into a rainbow (dispersion) because n varies slightly with wavelength."},eye3d:{challenge:{prompt:"Examine a short-sighted eye focused on a far object, then test how spectacles restore a crisp focus on the retina.",check:e=>e.tab(0)===1&&e.tab(1)===1&&e.num("Object distance",50)>=80},presets:[{name:"Short-Sighted Bare Eye",prompt:"Distant focus lands cleanly in front of the retina.",state:{tabs:[1,0],sliders:{"Object distance":90}}},{name:"Concave Spectacles Fix",prompt:"Diverging lens shifts focal spot onto the retina.",state:{tabs:[1,1],sliders:{"Object distance":90}}}],mentorTips:{openPlay:'Try "Cover half pupil" first\u2014predict whether half the picture vanishes or just dims.',misconception:"Thinking covering half a lens blocks half the image instead of dimming the whole image uniformly.",dinnerQuestion:"Why does squinting slightly\u2014or peeking through a tiny pinhole between fingers\u2014sharpen a blurred bus route number across Dadar circle?",cambridgeUnit:"Unit 7 \xB7 Lenses & The Human Eye"},yourNumbers:e=>{let t=e.num("Object distance",50),a=t>=98?"\u221E":Math.round(25*Math.pow(400,t/100)),i=["Ideal eye","Short-sighted (myopic)","Long-sighted (hyperopic)"][e.tab(0)]||"Eye";return`1/f = 1/d_o + 1/d_i  |  d_o = ${a}${a==="\u221E"?"":" cm"}, model retina = 2.00 cm behind the effective lens  |  ${i}`},cutaway:"The cornea provides most of the bending. Ciliary muscles change the crystalline lens shape to adjust focus; this drawing combines both into one effective thin lens.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: An ideal eye adjusts its lens curvature so rays from any distance meet sharply on the retina.",act:e=>{e.selectTab(0,0),e.selectTab(1,0),e.setSlider("Object distance",50)}},{title:"2. Close-up",caption:"2/5 Close-up: In a short-sighted eye, distant rays converge in front of the retina, blurring the image.",act:e=>{e.selectTab(0,1),e.setSlider("Object distance",90)}},{title:"3. Cut-away",caption:"3/5 Cut-away: Inside the eyeball, the ciliary muscle and crystalline lens reshape to focus.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: A diverging spectacle lens spreads incoming rays slightly so the eye\u2019s lens lands them right on the retina.",act:e=>e.selectTab(1,1)},{title:"5. Your turn",caption:'5/5 Your turn: Try "Cover half pupil" to see why the whole image stays complete but dimmer.',cutaway:!1}],idealised:"The cornea and crystalline lens are combined into a single thin adjustable lens for ray-tracing clarity."},interference:{challenge:{prompt:'Switch to "Stripes on a screen" and find what wavelength and slit spacing produce the widest bright interference fringes.',check:e=>e.tab(0)===1&&e.num("Wavelength",550)>=620&&e.num("Source spacing",.4)<=.3},presets:[{name:"Green Narrow Fringes",prompt:"550 nm green light across 0.40 mm slits.",state:{tabs:[1],sliders:{Wavelength:550,"Source spacing":.4}}},{name:"Red Wide Fringes",prompt:"Longer \u03BB and tighter slit spacing stretch \u0394y.",state:{tabs:[1],sliders:{Wavelength:660,"Source spacing":.25}}}],mentorTips:{openPlay:"Move ONLY Wavelength first, then ONLY Source spacing, watching \u0394y response.",misconception:"Assuming bringing the two slits closer together makes the interference bands narrower rather than wider.",dinnerQuestion:"Look closely through thin silk curtain folds at a distant Bandra streetlamp\u2014why do coloured fringes spread perpendicular to the threads?",cambridgeUnit:"Unit 7 \xB7 Double-Slit Interference"},yourNumbers:e=>{let t=e.num("Source spacing",.4),a=e.num("Wavelength",550),n=a*1e-6*1/(t*.001);return`\u0394y = \u03BB L \xF7 d = (${a} nm \xD7 1.0 m) \xF7 ${t.toFixed(2)} mm = ${n.toFixed(2)} mm between bright fringes`},cutaway:"Inside path difference \u0394r = d sin \u03B8: where crests from both slits arrive in step (\u0394r = m\u03BB) amplitudes add; where a crest meets a trough (\u0394r = (m+\xBD)\u03BB) they cancel to darkness.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Two coherent sources send overlapping waves whose crests and troughs add or cancel.",act:e=>{e.selectTab(0,0),e.setSlider("Source spacing",.4),e.setSlider("Wavelength",550)}},{title:"2. Close-up",caption:"2/5 Close-up: On a distant screen, constructive lanes form evenly spaced bright bands.",act:e=>e.selectTab(0,1)},{title:"3. Cut-away",caption:"3/5 Cut-away: Light plus light makes darkness wherever the two paths differ by half a wavelength.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Longer red wavelength (650 nm) or closer slits (0.25 mm) spreads the fringes wider apart.",act:e=>{e.setSlider("Wavelength",650),e.setSlider("Source spacing",.25)}},{title:"5. Your turn",caption:"5/5 Your turn: Sweep wavelength across the spectrum and watch fringe spacing respond.",cutaway:!1}],idealised:"The slits are treated as infinitely narrow point sources, so the wide single-slit diffraction envelope does not dim the outer fringes."},colourmix:{challenge:{prompt:'In "Light on a white wall", discover which combination of the three spotlight beams creates pure additive Yellow light.',check:e=>e.tab(0)===0&&e.num("Red",100)>=95&&e.num("Green",100)>=95&&e.num("Blue",100)<=5},presets:[{name:"Full White Overlap",prompt:"100% Red + Green + Blue light makes white.",state:{tabs:[0],sliders:{Red:100,Green:100,Blue:100}}},{name:"CMY Paint Filters",prompt:"Switch to subtractive pigment filters.",state:{tabs:[1],sliders:{Red:100,Green:100,Blue:0}}}],mentorTips:{openPlay:"Ask Kym to turn off just ONE spotlight from white light and predict the overlap colour.",misconception:"Assuming Red + Green light makes muddy brown because poster paints mix subtractively.",dinnerQuestion:"Under pure red LED street light with zero green or blue wavelengths, what colour does a bright green leaf look?",cambridgeUnit:"Unit 6 \xB7 Colour Addition & Filters"},yourNumbers:e=>{let t=e.num("Red",100),a=e.num("Green",100),i=e.num("Blue",100);return`${["Additive RGB light","Subtractive CMY pigment","Surface reflectance"][e.tab(0)]||"RGB"}: (${t}%, ${a}%, ${i}%)  \u2192  idealised three-channel colour model`},cutaway:"The retina has three cone types with overlapping wavelength responses. Different spectra can produce similar response patterns and appear the same colour; this RGB display illustrates that principle rather than modelling cone sensitivities.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Adding Red, Green, and Blue spotlights on a dark wall makes white where all three overlap.",act:e=>{e.selectTab(0,0),e.setSlider("Red",100),e.setSlider("Green",100),e.setSlider("Blue",100)}},{title:"2. Close-up",caption:"2/5 Close-up: Turning Blue to 0% leaves Red + Green light, which your eyes see as bright Yellow.",act:e=>e.setSlider("Blue",0)},{title:"3. Cut-away",caption:"3/5 Cut-away: Inside the retina\u2019s L, M, and S cone photoreceptors.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Paints work by subtraction\u2014each pigment steals wavelengths from white paper.",act:e=>e.selectTab(0,1)},{title:"5. Your turn",caption:"5/5 Your turn: Test lights, paints, and coloured objects under coloured lamps.",cutaway:!1}],idealised:"Screen sRGB primaries approximate monochromatic spectral lights and idealised block-filter pigments."},skycolour:{challenge:{prompt:"Lower the Sun close to the horizon on Earth and explain why the setting Sun turns orange-red while the overhead sky stays blue.",check:e=>e.tab(0)===0&&e.num("Sun height",45)<=4},presets:[{name:"Midday Blue Zenith",prompt:"Short blue wavelengths scatter down to your eye.",state:{tabs:[0],sliders:{"Sun height":60}}},{name:"Chowpatty Sunset (2\xB0)",prompt:"Long air mass strips blue light out of the direct Sun.",state:{tabs:[0],sliders:{"Sun height":2}}}],mentorTips:{openPlay:'Toggle "The Moon (no air)" at noon to see why air molecules create the blue vault.',misconception:"Thinking Earth\u2019s oceans reflect blue upward into the sky or that air turns blue only when polluted.",dinnerQuestion:"At Worli Sea Face sunset, why is the western horizon glowing fiery amber while someone glancing straight overhead still sees slate-blue sky?",cambridgeUnit:"Unit 7 \xB7 Scattering & Atmospheric Light"},yourNumbers:e=>{let t=e.num("Sun height",45);if(e.tab(0)===2)return"No atmosphere on the Moon \u2192 no molecular scattering or scattered blue sky";let a=750,i=Math.max(-.04,Math.sin(t*Math.PI/180)),n=Math.sqrt(a*a*i*i+2*a+1)-a*i;return`I_scat \u221D 1 \xF7 \u03BB\u2074  |  blue 450 nm scatters 5.86\xD7 more than red 700 nm  |  Sun ${t}\xB0 \u2192 curved-air path \u2248 ${n.toFixed(1)}\xD7 zenith`},cutaway:"Inside Rayleigh scattering: N\u2082 and O\u2082 molecules (0.3 nm wide) are much smaller than light wavelengths, oscillating like tiny dipole antennas that radiate strongly as 1/\u03BB\u2074.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: With the Sun high overhead, short blue wavelengths scatter across the sky into your eyes.",act:e=>{e.selectTab(0,0),e.setSlider("Sun height",60)}},{title:"2. Close-up",caption:"2/5 Close-up: At 2\xB0, this curved-air model gives about 20.6 times the zenith path. More blue and green are scattered out of the direct beam.",act:e=>e.setSlider("Sun height",2)},{title:"3. Cut-away",caption:"3/5 Cut-away: In this model, 450 nm blue light scatters 5.86 times as strongly as 700 nm red light.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: On the airless Moon, no scattering occurs\u2014the sky is pitch black even at noon.",act:e=>{e.selectTab(0,2),e.setSlider("Sun height",45)}},{title:"5. Your turn",caption:"5/5 Your turn: Sweep the Sun from noon to sunset across Earth, thin air, and the Moon.",cutaway:!1}],idealised:"Only Rayleigh molecular scattering (1/\u03BB\u2074) is calculated; larger dust and water droplets add whiter Mie scattering near the horizon."},circuit:{challenge:{prompt:"Power 3 series LEDs from a 9.0 V battery and determine both the shared loop current and the voltage left across the 330 \u03A9 resistor.",check:e=>Math.abs(e.num("Battery",9)-9)<.2&&e.tab(0)===2},presets:[{name:"Below LED Threshold",prompt:"6.0 V across four 2 V LEDs cannot turn them on.",state:{tabs:[3,0],sliders:{Battery:6}}},{name:"Energy-per-Coulomb Steps",prompt:"Inspect potential height around a 9 V, 3-LED loop.",state:{tabs:[2,1],sliders:{Battery:9}}},{name:"Rope Analogy",prompt:"Compare electrical loop to a continuous pulled rope.",state:{tabs:[1,2],sliders:{Battery:9}}}],mentorTips:{openPlay:"Ask Kym to compare the current counters at A, B, and C before touching any numbers.",misconception:'Thinking current gets "used up" as it passes through the resistor and LEDs (so C would read less than A).',dinnerQuestion:"When you switch on a bedroom lamp in Mumbai, why does it light instantly even though electrons drift slower than a snail?",cambridgeUnit:"Unit 9 \xB7 Electric Current & Voltage"},yourNumbers:e=>{let t=e.num("Battery",9),a=e.tab(0)+1,i=Math.max(0,(t-2*a)/330);return i>0?`I = (${t.toFixed(1)} \u2212 ${2*a}) V \xF7 330 \u03A9 = ${(1e3*i).toFixed(1)} mA  |  each LED \u2248 2 V; resistor = ${(330*i).toFixed(1)} V`:`${t.toFixed(1)} V \u2264 ${2*a} V threshold: I = 0 in this model; individual LED voltages are not resolved.`},cutaway:"The wire already contains mobile charge. A change in the electric field spreads around the circuit; carriers do not travel from the battery to fill an empty wire. When current flows, each coulomb transfers about 2 J at each LED and the remaining energy at the resistor.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Existing charge circulates around a closed loop; the same current crosses A, B and C.",act:e=>{e.selectTab(0,0),e.selectTab(1,0),e.setSlider("Battery",9)}},{title:"2. Close-up",caption:"2/5 Close-up: The battery raises energy per coulomb; the resistor and LEDs transfer it to their surroundings.",act:e=>e.selectTab(1,1)},{title:"3. Cut-away",caption:"3/5 Cut-away: Charge is conserved; energy is transferred at the circuit components.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: At 9 V, three 2 V LEDs leave 3 V across 330 \u03A9, giving about 9.1 mA.",act:e=>{e.setSlider("Battery",9),e.selectTab(0,2),e.selectTab(1,1)}},{title:"5. Your turn",caption:"5/5 Your turn: Lower the supply below the combined LED threshold and compare the whole-loop current.",cutaway:!1}],idealised:"Each conducting red LED is approximated by a 2 V drop and a 330 \u03A9 resistor limits the current. Below the combined threshold the model gives zero current and does not resolve individual LED voltages; real LED curves are gradual."},seriesparallel:{challenge:{prompt:"Wire 3 LEDs in parallel and unclip LED 1\u2014discover why the remaining branches keep full brightness while total battery current drops.",check:e=>e.tab(0)===1&&Math.abs(e.num("LEDs",2)-3)<.2&&/^Parallel with LED 1 unclipped:/i.test(e.readout())},presets:[{name:"Dim Series Chain",prompt:"3 LEDs sharing one 9 V loop.",state:{tabs:[0],sliders:{LEDs:3},custom:{unclipped:!1}}},{name:"3 Parallel Branches",prompt:"Each branch gets the full 9 V across the battery.",state:{tabs:[1],sliders:{LEDs:3},custom:{unclipped:!1}}},{name:"Schematic Diagram",prompt:"Switch to Cambridge IEC circuit symbols.",state:{tabs:[1],sliders:{LEDs:2},custom:{schematic:!0,unclipped:!1}}}],mentorTips:{openPlay:"Tap LED 1 directly on the canvas in both Series and Parallel modes to see what breaks.",misconception:"Thinking a battery always outputs a fixed current regardless of how many parallel branches are connected.",dinnerQuestion:"Why do all rooms in our apartment stay bright when one ceiling fan or bulb is switched off\u2014are they wired in series or parallel?",cambridgeUnit:"Unit 9 \xB7 Series & Parallel Circuits"},yourNumbers:e=>{let t=e.num("LEDs",2),a=e.tab(0)===1,i=/^(0 mA everywhere|Parallel with LED 1 unclipped)/.test(e.readout());if(a){let r=t-(i?1:0),o=1e3*7/330;return`Parallel: 9 V per branch = 2 V LED + 7 V resistor  |  ${r} connected branches \xD7 ${o.toFixed(1)} mA = ${(r*o).toFixed(1)} mA from battery`}let n=i?0:1e3*Math.max(0,9-2*t)/330;return`Series: 9 V = ${t} \xD7 2 V LED + ${(9-2*t).toFixed(0)} V resistor  |  loop current ${n.toFixed(1)} mA${i?" (open circuit)":""}`},cutaway:"Inside the parallel junction node: Kirchhoff\u2019s current law (I_in = I_1 + I_2 + I_3) splits the charge stream into independent lanes, each connected across the full battery voltage.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: In series, one single loop carries the same reduced current through every lamp.",act:e=>{e.selectTab(0,0),e.setSlider("LEDs",3)}},{title:"2. Close-up",caption:"2/5 Close-up: In parallel, each lamp gets its own direct lane across the battery and shines at full brightness.",act:e=>e.selectTab(0,1)},{title:"3. Cut-away",caption:"3/5 Cut-away: At the branch junction, current adds up while voltage stays equal across each rung.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Unclipping one lamp breaks a series loop completely, but leaves the other parallel branches running.",act:e=>e.clickBtn("Unclip")},{title:"5. Your turn",caption:"5/5 Your turn: Compare 1, 2, or 3 lamps in series and parallel.",cutaway:!1}],idealised:"The battery has zero internal resistance, so adding parallel branches never makes the battery terminal voltage sag."},field3d:{challenge:{prompt:"Test a strong 2.5 A current in the coil-and-magnet view, then reverse the current to see how the electromagnet poles flip.",check:e=>e.tab(0)===1&&e.num("Current",1.5)>=2.4},presets:[{name:"Straight Wire \xD8rsted",prompt:"Circular magnetic field lines around a straight current.",state:{tabs:[0],sliders:{Current:2}}},{name:"Strong Solenoid 2.5 A",prompt:"Wound coil dipole interacting with bar magnet.",state:{tabs:[1],sliders:{Current:2.5}}}],mentorTips:{openPlay:"Orbit the 3D coil and watch the compass needle before flipping current direction.",misconception:"Thinking a copper wire needs iron inside it to create any magnetic field at all.",dinnerQuestion:"Why do junkyard crane electromagnets drop scrap steel the instant power turns off, instead of staying permanently magnetised?",cambridgeUnit:"Unit 9 \xB7 Electromagnets & Magnetic Fields"},yourNumbers:e=>{let t=e.num("Current",1.5);return`${e.tab(0)===1?"Coil: schematic dipole field \u221D I; bar magnet stays fixed":"Straight wire B = \u03BC\u2080 I \xF7 (2\u03C0 r)"}  |  I = ${t.toFixed(1)} A  \u2192  field strength B \u221D ${t.toFixed(1)} A (right-hand grip rule)`},cutaway:"Inside the solenoid coil: circular magnetic field loops around each turn add together down the central tunnel to form a uniform North\u2013South bar-magnet field.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Current in a straight wire wraps magnetic field rings around the conductor (\xD8rsted\u2019s discovery).",act:e=>{e.selectTab(0,0),e.setSlider("Current",1.5)}},{title:"2. Close-up",caption:"2/5 Close-up: Winding the wire into a coil stacks those rings into a strong electromagnet.",act:e=>{e.selectTab(0,1),e.setSlider("Current",2.5)}},{title:"3. Cut-away",caption:"3/5 Cut-away: Inside the coil core, magnetic field lines run continuously from South to North.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Reversing current reverses the wire field. Against Earth\u2019s field, the compass swings to the other side of north, not generally through 180\xB0.",act:e=>e.clickBtn("Reverse")},{title:"5. Your turn",caption:"5/5 Your turn: Rotate the 3D field and test any current from 0 to 3.0 A.",cutaway:!1}],idealised:"The wire calculation uses vacuum permeability \u03BC\u2080. Its separate compass view includes Mumbai\u2019s 38.4 \u03BCT horizontal background; the coil/magnet field shapes are schematic dipoles."},magnetometer:{challenge:{prompt:'Explore the 3-axis magnetic readout or click "Hold" to freeze a reading in microteslas (\u03BCT).',check:e=>e.interacted||e.watched},presets:[{name:"Earth Field Baseline",prompt:"Inspect geomagnetic B_x, B_y, B_z magnitude (~43 \u03BCT).",state:{tabs:[]}}],mentorTips:{openPlay:"Rotate the phone/sensor smoothly and notice |B| stays near ~43 \u03BCT even while components swap signs.",misconception:"Confusing the vertical/horizontal axis projection with a change in Earth\u2019s actual magnetic strength.",dinnerQuestion:"Why does a navigation compass work inside an open Mumbai ferry deck yet spin unpredictably near iron train girders?",cambridgeUnit:"Unit 8 \xB7 Magnetic Fields & Sensors"},yourNumbers:()=>"|B| = \u221A(B_x\xB2 + B_y\xB2 + B_z\xB2)  |  Earth\u2019s field \u2248 25\u201365 \u03BCT (\u2248 43 \u03BCT in Mumbai)",cutaway:"One possible chip design uses the Hall effect: moving charges are deflected sideways by a magnetic field, producing a voltage. Other phone chips use magnetoresistive materials; the displayed axes do not identify the chip design.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Even far from any fridge magnet, a magnetometer reads Earth\u2019s ~43 \u03BCT background field."},{title:"2. Close-up",caption:"2/5 Close-up: A small magnet\u2019s far field falls approximately as 1/r\xB3; a long straight current-carrying wire instead gives B \u221D 1/r."},{title:"3. Cut-away",caption:"3/5 Cut-away: Three sensor axes measure B_x, B_y and B_z; keep the screen flat before interpreting the screen-normal component as vertical.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Flipping the magnet reverses the sign of the component along the sensor axis."},{title:"5. Your turn",caption:"5/5 Your turn: Use a device magnetometer or inspect the reference reading.",cutaway:!1}],idealised:"Phone calibration varies. Internal magnets, nearby steel and sensor offsets can shift the readings; this display does not guarantee hard-iron correction or world-coordinate orientation."},induction:{challenge:{prompt:"Maximise the coil turns and move the magnet rapidly through the coil to discover what produces the largest induced voltage spike.",check:e=>e.num("Turns",1)>=2&&(e.interacted||e.watched)},presets:[{name:"Stationary Magnet",prompt:"Strong magnet sitting still inside coil produces 0 V.",state:{sliders:{Turns:2}}},{name:"200-Turn Dynamo Coil",prompt:"Maximum coil turns ready for rapid flux change.",state:{sliders:{Turns:3}}}],mentorTips:{openPlay:"Park the magnet completely inside the coil first\u2014ask why the voltmeter drops right back to zero!",misconception:"Thinking a strong magnet sitting inside a coil generates continuous steady electricity.",dinnerQuestion:"What actually turns inside a wind turbine or hydroelectric generator at Koyna to keep electricity flowing?",cambridgeUnit:"Unit 9 \xB7 Electromagnetic Induction"},yourNumbers:e=>{let t=e.num("Turns",1);return`\u03B5 = \u2212N \xD7 \u0394\u03A6_B \xF7 \u0394t  |  N = ${[1,10,50,200][t]||50} turns  \u2192  stationary magnet gives \u0394\u03A6_B/\u0394t = 0 V`},cutaway:"Inside Faraday\u2019s law: a changing magnetic flux \u03A6_B through the coil curls an electric field around the copper loops, pushing conduction electrons only while the magnet moves.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: A magnet sitting still inside the coil produces zero voltage, no matter how strong it is.",act:e=>e.setSlider("Turns",1)},{title:"2. Close-up",caption:"2/5 Close-up: Plunging the magnet in or pulling it out deflects the galvanometer in opposite directions.",act:e=>e.clickBtn("Nudge")},{title:"3. Cut-away",caption:"3/5 Cut-away: Only changing magnetic flux (\u0394\u03A6_B/\u0394t) drives an induced current.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Increasing the number of coil turns multiplies the induced voltage spike.",act:e=>{e.setSlider("Turns",3),e.clickBtn("Nudge")}},{title:"5. Your turn",caption:"5/5 Your turn: Drag the magnet fast or slow and flip N \u2194 S.",cutaway:!1}],idealised:"Self-inductance of the coil is neglected so current follows the induced EMF instantaneously."},shadow:{challenge:{prompt:"Match Eratosthenes\u2019 Syene\u2013Alexandria solstice meridian separation and shallow shadow tilt to estimate Earth\u2019s full circumference from parallel sunbeams!",check:e=>Math.abs(e.num("Distance",5e3)-5e3)<=250&&Math.abs(e.num("Shadow angle",7.2)-7.2)<=.3},presets:[{name:"Eratosthenes 7.2\xB0 Setup",prompt:"1/50th of a circle \xD7 5,000 stadia gives ~40,000 km.",state:{tabs:[1],sliders:{Distance:5e3,"Shadow angle":7.2}}},{name:"Steep Shadow Check",prompt:"Larger angle for the same road implies a tinier globe.",state:{tabs:[1],sliders:{Distance:5e3,"Shadow angle":18}}}],mentorTips:{openPlay:"Notice BOTH parallel Sun beams must stay parallel for the shadow angle to match the central Earth angle.",misconception:"Thinking a stick shadow only changes length if Earth were tiny and the Sun sat right above Egypt.",dinnerQuestion:"If Eratosthenes had lived between Mumbai and Ahmedabad (~450 km north\u2013south), about what noon shadow difference would solstice sticks cast?",cambridgeUnit:"Unit 1 \xB7 Measuring Planet Earth"},yourNumbers:e=>{let t=e.num("Distance",5e3),a=e.num("Shadow angle",7.2),i=360/Math.max(.5,a),n=Math.round(t*i),r=[192,1e3/6,160,null][e.tab(0)];if(r===null)return`C = ${n.toLocaleString("en-GB")} stadia; kilometres require a known stadion length.`;let o=Math.round(n*r/1e3);return`C = (360\xB0 \xF7 \u03B8) \xD7 d = (360\xB0 \xF7 ${a.toFixed(1)}\xB0) \xD7 ${t} stadia \u2248 ${o.toLocaleString("en-GB")} km (true Earth: 40,008 km)`},cutaway:"Inside the alternate-interior geometry: because the Sun is 150 million km away, its rays arrive parallel; the stick\u2019s shadow angle at Alexandria equals the angle between the two cities at Earth\u2019s centre.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: At noon on the solstice, a vertical well at Syene has no shadow while Alexandria casts a 7.2\xB0 shadow.",act:e=>{e.setSlider("Distance",5e3),e.setSlider("Shadow angle",7.2)}},{title:"2. Close-up",caption:"2/5 Close-up: Parallel sunbeams mean the 7.2\xB0 shadow angle equals the central angle between the two cities."},{title:"3. Cut-away",caption:"3/5 Cut-away: 7.2\xB0 is exactly 1/50th of a full 360\xB0 circle, so Earth\u2019s circumference is 50 \xD7 the distance.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Compare 192 m, about 166.7 m and 160 m stadia; an unknown stadion length cannot determine kilometres.",act:e=>e.selectTab(0,1)},{title:"5. Your turn",caption:"5/5 Your turn: Adjust distance and shadow angle to measure the planet.",cutaway:!1}],idealised:"Syene and Alexandria are treated as lying on the exact same north\u2013south meridian (in reality they differ by ~3\xB0 of longitude)."},seasons:{challenge:{prompt:"Follow noon sunlight at the June solstice across Mumbai, the Equator, the Tropic of Cancer, and higher northern latitudes\u2014what steers summer warmth, Sun altitude or distance?",check:e=>Math.abs(e.num("Date",172)-172)<=15&&e.tab(0)>0},presets:[{name:"Mumbai Solstice (19\xB0 N)",prompt:"Compare June overhead beam vs Dec angle.",state:{tabs:[0],sliders:{Date:172}}},{name:"December Paris Tilt",prompt:"Low winter Sun spreads photons wider.",state:{tabs:[3],sliders:{Date:355}}}],mentorTips:{openPlay:"Ask Kym whether Earth is actually closest to the Sun in June or January (surprise: January!).",misconception:"Believing summer happens because Earth orbits closer to the Sun in June.",dinnerQuestion:"In late May before Mumbai clouds arrive, why does the Sun pass almost straight overhead near Gateway of India around noon?",cambridgeUnit:"Unit 2 \xB7 Earth\u2019s Axial Tilt & Seasons"},yourNumbers:e=>{let t=/^Tilted (\d+)/.exec(e.readout());if(t){let s=+t[1],c=1/Math.cos(s*Math.PI/180);return`Torch ${s}\xB0 from vertical \u2192 footprint ${c.toFixed(2)}\xD7 the area; ${(100/c).toFixed(0)}% light per square metre`}let a=e.num("Date",172),i=-23.44*Math.cos(2*Math.PI*(a+10)/365),n=[19.08,0,23.44,48.85][e.tab(0)]??19.08,r=90-Math.abs(n-i),o=Math.sin(r*Math.PI/180);return`Latitude ${n.toFixed(2)}\xB0 N  |  \u03B4_Sun = ${i.toFixed(1)}\xB0  |  noon altitude ${r.toFixed(1)}\xB0 \u2192 ${(100*o).toFixed(0)}% of overhead energy per m\xB2`},cutaway:"Inside the tilted beam: a 1 m\xB2 bundle of sunlight hitting the ground at 30\xB0 spreads over 1/sin(30\xB0) = 2.0 m\xB2, halving the watts warming each square metre.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Earth\u2019s 23.4\xB0 axis keeps pointing toward Polaris all year as the planet orbits the Sun.",act:e=>{e.selectTab(0,0),e.setSlider("Date",172)}},{title:"2. Close-up",caption:"2/5 Close-up: In June the northern hemisphere leans toward the Sun, making noon sunlight steep and concentrated.",act:e=>e.selectTab(0,1)},{title:"3. Cut-away",caption:"3/5 Cut-away: Why beam angle\u2014not Earth\u2019s tiny 3% orbital distance change\u2014drives summer and winter.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: In December (day 355), Paris has a lower noon Sun than Mumbai. Compare the wider footprint and shorter daylight.",act:e=>{e.selectTab(0,3),e.setSlider("Date",355)}},{title:"5. Your turn",caption:"5/5 Your turn: Scrub through the year or try the torch-on-graph-paper view.",cutaway:!1}],idealised:"Atmospheric absorption and seasonal thermal lag of the oceans (which delays peak summer temperatures by ~4 weeks) are omitted."},phases:{challenge:{prompt:'Switch to "From Mumbai" and advance the lunar cycle until the Moon\u2019s near face appears completely illuminated (Full Moon).',check:e=>e.tab(0)===1&&Math.abs(e.num("Day of the month",4)-14.8)<=1.2},presets:[{name:"First Quarter Half-Moon",prompt:"Orbit at 90\xB0 gives a half-lit disc.",state:{tabs:[0],sliders:{"Day of the month":7.4}}},{name:"Mumbai Crescent View",prompt:"See a waxing crescent from Earth\u2019s surface.",state:{tabs:[1],sliders:{"Day of the month":4}}}],mentorTips:{openPlay:"Notice from above space that 50% of the Moon is ALWAYS sunlit\u2014even at New Moon!",misconception:"Believing crescent or half moons are caused by Earth\u2019s shadow blocking the Sun (eclipses vs phases).",dinnerQuestion:"On a First Quarter afternoon when you spot a crisp half-moon in the Mumbai sky, where is the Sun relative to the Moon?",cambridgeUnit:"Unit 3 \xB7 Earth, Moon & Space Geometry"},yourNumbers:e=>{let t=e.num("Day of the month",4),a=t/29.5*2*Math.PI,i=Math.round((1-Math.cos(a))/2*100);return`Day ${t.toFixed(1)} of 29.5  |  orbital phase angle \u03C6 = ${Math.round(a*180/Math.PI)}\xB0  \u2192  earth-facing lit fraction = \xBD(1 \u2212 cos \u03C6) = ${i}%`},cutaway:"Inside the geometry of phases: the Sun always illuminates 50% of the lunar sphere; phases are simply how much of that sunlit hemisphere faces Earth as the Moon orbits.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Seen from above the orbit, half the Moon is always sunlit\u2014Earth\u2019s shadow is nowhere near it.",act:e=>{e.selectTab(0,0),e.setSlider("Day of the month",4)}},{title:"2. Close-up",caption:"2/5 Close-up: At Day 7.4 (First Quarter), we look side-on at the terminator and see a half-moon.",act:e=>e.setSlider("Day of the month",7.5)},{title:"3. Cut-away",caption:"3/5 Cut-away: Compare the Moon\u2019s sunlit hemisphere with its Earth-facing phase. Real orbital inclination prevents most full moons becoming eclipses; inclination is not simulated here.",cutaway:!0,act:e=>e.setSlider("Day of the month",14.8)},{title:"4. Side-on trend",caption:'4/5 Trend: Switching to "From Mumbai" shows the waxing and waning crescent views from the ground.',act:e=>e.selectTab(0,1)},{title:"5. Your turn",caption:"5/5 Your turn: Scrub through all 29.5 days and toggle true scale.",cutaway:!1}],idealised:"The lunar orbit is circular and coplanar in this illustration. Orbital inclination, eclipse dates and libration are omitted."},parallax:{challenge:{prompt:"Look through the telescope across a 6-month Earth baseline (January to July) to measure the star\u2019s apparent annual wobble.",check:e=>e.tab(0)===1&&e.num("Month",0)>=5&&e.num("Month",0)<=7},presets:[{name:"Nearby Star (1.6 pc)",prompt:"Clear half-year shift p across Earth\u2019s 2 AU orbit.",state:{tabs:[1],sliders:{"Star distance":10,Month:6}}},{name:"Distant Star (10 pc)",prompt:"Smaller wobble means greater distance d = 1/p.",state:{tabs:[1],sliders:{"Star distance":50,Month:6}}}],mentorTips:{openPlay:"Hold a thumb at arm\u2019s length and wink left\u2013right eyes before dragging Month from Jan to Jul.",misconception:"Thinking parallax happens because the star physically moves back and forth every six months.",dinnerQuestion:"Why did ancient Greek astronomers fail to see nearby stars wobble, even though Earth actually orbits 300 million km side to side?",cambridgeUnit:"Unit 9 \xB7 Stellar Distances & Parallax"},yourNumbers:e=>{let t=e.num("Star distance",20),a=Math.pow(10,t/50);return`d (parsecs) = 1 \xF7 p (arcsec)  |  January \u2194 July = 2 AU and shift 2p; p is the half-shift  \u2192  p = ${(1/a).toFixed(3)}\u2033, d = ${a.toFixed(1)} pc (${(a*3.26).toFixed(1)} ly)`},cutaway:"Inside the 1 AU triangle: 1 parsec is the distance where Earth\u2019s 150-million-km orbital radius subtends an angle of 1 arcsecond (1/3,600 of a degree, the width of a rupee coin at 5 km).",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: As Earth moves from January to July, our sightline to a nearby star tilts against distant background stars.",act:e=>{e.selectTab(0,0),e.setSlider("Month",0),e.setSlider("Star distance",10)}},{title:"2. Close-up",caption:"2/5 Close-up: Six months later (July), Earth is 300 million km to the other side, shifting the star\u2019s apparent position.",act:e=>e.setSlider("Month",6)},{title:"3. Cut-away",caption:"3/5 Cut-away: How a tiny parallax angle p in arcseconds gives distance d = 1/p parsecs by pure trigonometry.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Through the telescope, moving the star farther away shrinks its annual wobble.",act:e=>{e.selectTab(0,1),e.setSlider("Star distance",50)}},{title:"5. Your turn",caption:"5/5 Your turn: Switch telescope view and sweep between January and July.",cutaway:!1}],idealised:"The overhead triangle exaggerates angles. The telescope view uses its labelled 1.0 arcsecond scale bar; the circular annual trace applies near an orbital pole."},expansion:{challenge:{prompt:"Move your observer perch to an outer galaxy and stretch space significantly\u2014does Hubble\u2019s linear expansion law still look centred around you?",check:e=>e.tab(0)===2&&Math.abs(e.num("Stretch factor",1)-2)<=.08},presets:[{name:"Central Galaxy View",prompt:"Twice as far recedes twice as fast from 7 cm.",state:{tabs:[1],sliders:{"Stretch factor":2}}},{name:"Outer Ant Frame",prompt:"Switch origin to 12 cm\u2014identical Hubble slope.",state:{tabs:[2],sliders:{"Stretch factor":2}}}],mentorTips:{openPlay:"Notice EVERY dot appears to flee the ant you pick, proving there is no centre of expansion.",misconception:"Imagining the Big Bang as an explosion flying from one spot inside empty space.",dinnerQuestion:"When raisin bread rises evenly in a Colaba bakery oven, which raisin sees its neighbours moving away slowest\u2014central ones or every raisin equally?",cambridgeUnit:"Unit 9 \xB7 Expanding Universe & Redshift"},yourNumbers:e=>{let t=e.num("Stretch factor",1),a=[2,7,12][e.tab(0)]||7;return`v = H\u2080 d  |  stretch factor s = \xD7${t.toFixed(2)} (home ant at ${a} cm)  \u2192  every distance d\u2080 becomes ${t.toFixed(2)} \xD7 d\u2080`},cutaway:"Inside metric expansion: galaxies are not flying like shrapnel through pre-existing space; the metric grid between unbound galaxy clusters stretches uniformly everywhere.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: As the elastic band stretches, every button moves away from your chosen home button.",act:e=>{e.selectTab(0,1),e.setSlider("Stretch factor",1)}},{title:"2. Close-up",caption:"2/5 Close-up: A neighbour twice as far away recedes twice as fast\u2014a straight line on v vs d.",act:e=>e.setSlider("Stretch factor",2)},{title:"3. Cut-away",caption:"3/5 Cut-away: Why there is no special centre\u2014every observer sees the exact same v = H\u2080 d slope.",cutaway:!0,act:e=>e.selectTab(0,2)},{title:"4. Side-on trend",caption:"4/5 Trend: Light waves travelling through stretching space are stretched too, shifting toward the red.",act:e=>e.clickBtn("Mode")},{title:"5. Your turn",caption:"5/5 Your turn: Switch home galaxies and stretch the universe.",cutaway:!1}],idealised:"Local gravitational pulls (such as Andromeda falling toward the Milky Way) are omitted to show pure cosmological Hubble flow."},selftest:{challenge:{prompt:"Raise spring stiffness above 18 N/m and observe how oscillation frequency responds to stronger restoring force.",check:e=>e.num("Stiffness",10)>=18},yourNumbers:e=>{let t=e.num("Stiffness",10),a=Math.sqrt(t).toFixed(2);return`F = \u2212k x  |  k = ${t} N/m  \u2192  \u03C9 = \u221A(k/m) = ${a} rad/s`},cutaway:"Inside Hooke\u2019s law: restoring force is proportional to displacement from equilibrium.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: The mass oscillates back and forth around equilibrium."},{title:"2. Close-up",caption:"2/5 Close-up: Stiffer springs oscillate faster.",act:e=>e.setSlider("Stiffness",20)},{title:"3. Cut-away",caption:"3/5 Cut-away: Restoring force always points toward the centre.",cutaway:!0},{title:"4. Side-on trend",caption:"4/5 Trend: Period scales inversely with \u221Ak."},{title:"5. Your turn",caption:"5/5 Your turn: Adjust stiffness or play a tone.",cutaway:!1}],idealised:"Damping is omitted so the oscillation amplitude stays constant."},atlas_period:l("Inspect the 3D pendulum and spring pair, or switch to X-ray / Section cutaway mode to see why 4\xD7 length gives 2\xD7 period.",e=>e.interacted||e.watched,()=>"T = 2\u03C0 \u221A(L \xF7 g)  |  L\u2082 = 4 L\u2081  \u2192  T\u2082 = \u221A4 \xD7 T\u2081 = 2 T\u2081","Inside the small-angle restoring torque: F_restore \u2248 \u2212(mg/L) s, so longer L softens stiffness while increasing arc length.","Two springs and two pendulums side by side in 3D.",void 0,"The 4\xD7 longer pendulum takes exactly twice as long per swing.",void 0,"Restoring force scales as 1/L, giving T \u221D \u221AL.","A 4\xD7 heavier mass on an identical spring also doubles the period (T = 2\u03C0\u221A(m/k)).",void 0,"Small-angle approximation sin \u03B8 \u2248 \u03B8 and zero air resistance keep period independent of amplitude.",[{name:"Side-by-Side Pair",prompt:"Count swings of the 4\xD7 length pendulum.",state:{tabs:[6,0]}},{name:"X-Ray Internal View",prompt:"Reveal spring coils inside the frame.",state:{tabs:[6,1]}}],{openPlay:"Count how many times the short pendulum returns while the 4\xD7 long one finishes one swing.",misconception:"Thinking doubling pendulum bob mass or doubling length doubles the period.",dinnerQuestion:"If you lengthen a monsoon swing rope at Hanging Gardens fourfold, how much slower does each back-and-forth beat become?",cambridgeUnit:"Unit 6 \xB7 Pendulum & Spring Period"}),atlas_ch00:l("Move the ship farther out past the coastal curve or align the ruler straight overhead to eliminate parallax shift!",e=>e.num("Ship distance",13)>=15||Math.abs(e.num("Ruler viewing angle",18))<=2||e.interacted,e=>{let t=e.num("Observer eye height",2),a=e.num("Ship distance",13);return`d_hz = \u221A(2 R_E h) = ${Math.sqrt(12742*t*.001).toFixed(2)} km (h = ${t.toFixed(1)} m)  |  Ship at ${a.toFixed(1)} km`},"The horizon is where your line of sight grazes Earth\u2019s 6,371 km sphere; in rain gauges, V = A \xD7 h cancels mouth area A.","An outbound ship drops hull-first behind the curved sea.",e=>e.setSlider("Ship distance",16),"Raising eye height h pushes the horizon kilometres farther out.",e=>e.setSlider("Observer eye height",15),"Geometry decides what is hidden behind Earth\u2019s curve or shifted by parallax.","Looking straight down (\u03B8 = 0\xB0) reduces parallax \u0394x = t tan \u03B8 to 0 mm.",e=>e.setSlider("Ruler viewing angle",0),"Atmospheric refraction over warm seawater is omitted.",[{name:"Hull-Down Cargo Ship",prompt:"Observe Earth curvature hiding the hull beyond the horizon.",state:{tabs:[0,0],sliders:{"Ship distance":16}}},{name:"Zero Parallax Look",prompt:"Read the scale vertically perpendicular.",state:{tabs:[2,0],sliders:{"Ruler viewing angle":0}}}],{openPlay:"Orbit to look flush across the ruler thickness and watch the parallax shift appear.",misconception:"Thinking binoculars bring an ocean-hidden ship hull back above the horizon.",dinnerQuestion:"From the Worli Sea Link parapet compared to the sandy shore, how many extra kilometres of Arabian Sea can you see?",cambridgeUnit:"Unit 1 \xB7 Measurement, Parallax & Scale"}),atlas_ch01:l("Steepen Galileo\u2019s bronze-ball incline to accelerate fall, or compare two opposing trains in relative motion!",e=>e.num("Galileo ramp angle",12)>=18||e.interacted,e=>{let t=e.num("Galileo ramp angle",12);return`a = (5/7) g sin(${t}\xB0) = ${(7.000000000000001*Math.sin(t*Math.PI/180)).toFixed(2)} m/s\xB2  |  odd-number gaps 1 : 3 : 5 : 7`},"Tilting the groove dilutes gravity by sin \u03B8 (and rolling inertia by 5/7), slowing fall so bell gates verify \u0394x \u221D t\xB2.","Platform frame S and carriage frame S\u2032 relate positions by x\u2032 = x \u2212 v t.",void 0,"On Galileo\u2019s ramp, bells at 1, 4, 9, and 16 units ring on a steady beat.",e=>e.setSlider("Galileo ramp angle",16),"At the peak of a vertical toss, v = 0 while acceleration stays \u22129.8 m/s\xB2.","Opposite trains add their speeds in v_AB = v_A \u2212 v_B.",e=>e.setSlider("Train A ground velocity",18),"Rolling resistance and air drag on the bronze sphere are neglected.",[{name:"Galileo Steep Ramp",prompt:"Trace 1 : 3 : 5 : 7 equal-time distances.",state:{tabs:[1,0],sliders:{"Galileo ramp angle":18}}},{name:"Opposing Local Trains",prompt:"Compare velocity addition across frames.",state:{tabs:[3,0],sliders:{"Train A ground velocity":18}}}],{openPlay:"Space the bells equally vs 1, 4, 9, 16 along the groove\u2014which pattern sounds a steady beat?",misconception:"Believing acceleration becomes zero at the highest point of an upward toss.",dinnerQuestion:"On a Central Line fast train passing another train opposite at Bandra, why does it seem to blur by twice as fast?",cambridgeUnit:"Unit 1 \xB7 Relative Motion & Constant Acceleration"}),atlas_ch02:l("Flatten Galileo\u2019s second recovery ramp toward horizontal, or push the block hard enough to break static friction!",e=>e.num("Galileo recovery slope",14)<=2||e.num("Horizontal push",22)>=26||e.interacted,e=>{let t=e.num("Horizontal push",22),a=e.num("Block mass",5),i=.5*a*9.8,n=.35*a*9.8;return t>i?`F (${t} N) > f_s,max (${i.toFixed(1)} N) \u2192 SLIDING a = ${((t-n)/a).toFixed(2)} m/s\xB2`:`F (${t} N) \u2264 f_s,max (${i.toFixed(1)} N) \u2192 LOCKED (a = 0)`},"Polished surfaces touch at micron-scale asperity peaks whose cold-welded tips shear when F_push exceeds \u03BC_s N.","On Galileo\u2019s double ramp, the ball climbs back to its starting height h.",e=>e.setSlider("Galileo recovery slope",15),"Flattening the second slope toward 0\xB0 sends run distance L = h / sin \u03B8\u2082 to infinity!",e=>e.setSlider("Galileo recovery slope",0),"Inside microscopic surface asperities under normal load N.","Pushing above \u03BC_s N breaks static welds onto the lower kinetic plateau \u03BC_k N.",e=>e.setSlider("Horizontal push",32),"Amontons\u2013Coulomb friction treats \u03BC_s and \u03BC_k as constant across sliding speeds.",[{name:"Galileo Flat Limit",prompt:"Flatten second ramp toward perpetual motion.",state:{tabs:[0,0],sliders:{"Galileo recovery slope":0}}},{name:"Break Static Welds",prompt:"Exceed \u03BC_s N threshold to trigger sliding.",state:{tabs:[2,0],sliders:{"Horizontal push":32}}}],{openPlay:"Switch to Section cutaway on the friction block to inspect the microscopic contact peaks.",misconception:"Assuming an object moving forward must always have a net forward force pushing it.",dinnerQuestion:"Why does pushing a heavy fridge across kitchen tiles take a hard initial shove yet slightly less force once moving?",cambridgeUnit:"Unit 2 \xB7 Inertia & Friction Peaks"}),atlas_ch03:l("Increase the forward pull on the three-car train and discover how tension steps down from coupling to coupling!",e=>e.num("Applied pull force",24)>=36||e.interacted,e=>{let t=e.num("Applied pull force",24),a=e.num("Test cart mass",3);return`a = F \xF7 m = ${(t/a).toFixed(2)} m/s\xB2  |  3-car tensions: ${t} N : ${(2*t/3).toFixed(0)} N : ${(t/3).toFixed(0)} N`},"Each coupling pulls only the mass trailing behind it; a rocket accelerates in vacuum by pushing its own exhaust gas.","Doubling net force doubles acceleration; doubling mass halves it.",e=>e.setSlider("Applied pull force",24),"Along a 3-car train, tension drops 3ma \u2192 2ma \u2192 1ma from front to rear.",e=>e.setSlider("Applied pull force",36),"Inside two hooked spring scales, F_AB = \u2212F_BA holds at every instant.","Faster rocket exhaust speed v_ex linearly boosts thrust F = v_ex dm/dt.",e=>e.setSlider("Rocket exhaust speed",3400),"Coupling hooks and spring scale casings are treated as massless.",[{name:"Three-Car Tension Ladder",prompt:"Compare 3 : 2 : 1 tension ratio along couplings.",state:{tabs:[1,0],sliders:{"Applied pull force":36}}},{name:"Vacuum Rocket Exhaust",prompt:"Inspect recoil thrust without pushing air.",state:{tabs:[3,0],sliders:{"Rocket exhaust speed":3400}}}],{openPlay:"Ask Kym whether the front coupling or rear coupling snaps first when pulling three identical bogies.",misconception:"Thinking action and reaction cancel each other out because they are equal and opposite.",dinnerQuestion:"How can an ISRO rocket steer and speed up in empty space if there is no air behind the nozzle to push against?",cambridgeUnit:"Unit 2 \xB7 Newton\u2019s Second & Third Laws"}),atlas_ch04:l("Flick the twin coin faster horizontally\u2014does extra sideways speed delay how soon both coins strike the table?",e=>e.num("Horizontal flick speed",4.5)>=6.5||e.interacted,e=>{let t=e.num("Release table height",1.25),a=e.num("Horizontal flick speed",4.5),i=Math.sqrt(2*t/9.8);return`t_fall = \u221A(2h \xF7 g) = ${i.toFixed(3)} s (independent of v_x!)  |  range x = v_x t = ${(a*i).toFixed(2)} m`},"Gravity pulls only along vertical y while horizontal v_x stays constant; on a circle, \u0394v = v\u2082 \u2212 v\u2081 points straight inward.","One coin drops straight down while its twin shoots out horizontally at v_x.",e=>e.setSlider("Horizontal flick speed",4.5),"Horizontal strobe bars prove both coins share the exact same height y(t) at every instant.",e=>e.setSlider("Horizontal flick speed",7.5),"Why velocity change \u0394v in uniform circular motion points radially inward.","Doubling orbital speed v quadruples inward centripetal acceleration a_c = v\xB2/r.",e=>e.setSlider("Orbital tangent speed",8),"Air resistance is omitted so horizontal and vertical motions are strictly independent.",[{name:"High-Speed Twin Coins",prompt:"Check simultaneous table impact despite fast v_x.",state:{tabs:[0,0],sliders:{"Horizontal flick speed":7.5}}},{name:"Vector \u0394v Turning",prompt:"See inward acceleration at constant orbital speed.",state:{tabs:[2,0],sliders:{"Orbital tangent speed":8}}}],{openPlay:"Line the 3D camera edge-on to check the horizontal strobe planes through both coins.",misconception:"Thinking a fast horizontal projectile stays airborne longer because it fights gravity sideways.",dinnerQuestion:"Does a carrom striker flying horizontally off a table edge hit the Mumbai marble floor any later than one dropped beside it?",cambridgeUnit:"Unit 4 \xB7 2D Projectiles & Circular Acceleration"}),atlas_ch05:l("Inspect gravity\u2019s fall-off at lunar distance, then stretch a comet orbit\u2019s eccentricity to compare perihelion and aphelion speeds!",e=>e.num("Orbital eccentricity",.55)>=.7||e.interacted,e=>{let t=e.num("Orbit distance",60),a=e.num("Orbital eccentricity",.55);return`At r = ${t} R_E: 1-s drop = 4.9 m \xF7 ${t}\xB2 = ${(4900/(t*t)).toFixed(2)} mm  |  v_p/v_a = ${((1+a)/(1-a)).toFixed(2)}\xD7`},"Inside Cavendish\u2019s box: a quartz torsion fibre twists under a 1.5 \xD7 10\u207B\u2077 N pull between lead spheres, deflecting a mirror beam.","At 60 R_E, gravity is diluted by 3,600\xD7 so the Moon falls 1.36 mm/s beneath its tangent.",e=>e.setSlider("Orbit distance",60),"A taut loop of string around two focal pins traces an ellipse with r\u2081 + r\u2082 = 2a.",e=>e.setSlider("Orbital eccentricity",.65),"Inside Cavendish\u2019s 1798 torsion balance and optical lever mirror.","Comets sweep equal areas in equal times, racing past perihelion.",e=>e.setSlider("Orbital eccentricity",.8),"Two-body Keplerian orbits neglect perturbations from neighbouring planets.",[{name:"60 R_E Moon Fall",prompt:"Verify 1/r\xB2 gravity dilution at lunar orbit.",state:{tabs:[0,0],sliders:{"Orbit distance":60}}},{name:"High-Eccentricity Comet",prompt:"Contrast perihelion race against aphelion drift.",state:{tabs:[2,0],sliders:{"Orbital eccentricity":.8}}}],{openPlay:"Inspect the Cavendish box in X-ray view to see how the optical lever amplifies micro-forces.",misconception:"Thinking astronauts float or comets orbit because Earth or space sits completely beyond gravity.",dinnerQuestion:"Why does Halley\u2019s Comet whip past the inner Sun in a few months yet take decades to creep past Neptune?",cambridgeUnit:"Unit 4 \xB7 Inverse-Square Gravity & Orbits"}),atlas_ch06:l("Fill the slotted water bottle deeper to accelerate the bottom jet, or drop ambient air pressure to watch the mercury barometer react!",e=>e.num("Bottle water column",.45)>=.55||e.num("External atmospheric pressure",101.3)<=75||e.interacted,e=>{let t=e.num("Bottle water column",.45),a=e.num("External atmospheric pressure",101.3);return`\u0394P_bottom = \u03C1gH = ${(9.8*t).toFixed(2)} kPa  |  P_atm = ${a.toFixed(1)} kPa \u2192 ${(a*1e3/133231*1e3).toFixed(0)} mm Hg`},"Fluid pressure P = P\u2080 + \u03C1gh depends only on vertical depth h, while air molecules hammer upward on an inverted glass card with ~390 N.","Deeper holes experience greater pressure \u03C1gh and shoot faster jets v = \u221A(2gh).",e=>e.setSlider("Bottle water column",.55),"Sea-level air pressure (101.3 kPa) holds up 760 mm of dense mercury.",e=>e.setSlider("External atmospheric pressure",101.3),"At high altitude, lower P_atm lets the mercury column sink.","Upward atmospheric force on a postcard exceeds the weight of 12 cm of water by 86\xD7!",e=>e.setSlider("External atmospheric pressure",65),"Viscous nozzle losses and orifice surface tension are omitted.",[{name:"High Bottle Head",prompt:"Compare top vs middle vs bottom jet arcs.",state:{tabs:[0,0],sliders:{"Bottle water column":.58}}},{name:"Lonavala Hill Barometer",prompt:"Lower P_atm and track mercury height drop.",state:{tabs:[1,0],sliders:{"External atmospheric pressure":75}}}],{openPlay:"Ask Kym why the top hole shoots a weak steep arc while the bottom hole fires almost horizontally.",misconception:'Thinking a "suction force" pulls drinks up a straw rather than external atmospheric pressure pushing.',dinnerQuestion:"If you carry Torricelli\u2019s mercury barometer up Sahyadri cliffs at Matheran, does the mercury rise or fall\u2014and why?",cambridgeUnit:"Unit 3 \xB7 Fluid Jets & Air Pressure"}),atlas_ch07:l("Double a falling sphere\u2019s impact speed into clay to test whether crater depth doubles or quadruples!",e=>Math.abs(e.num("Clay test impact speed",4)-4)<=.6&&e.interacted,e=>{let t=e.num("Clay test impact speed",4),a=e.num("Household appliance load",1500),i=.5*t*t;return`E_k = \xBDmv\xB2 = ${i.toFixed(1)} J \u2192 dent d = ${(i/2).toFixed(2)} cm  |  ${a} W \xD7 180 h = ${(a*180/1e3).toFixed(0)} kWh`},"Stopping a sphere in clay requires work W = F_clay d = \xBDmv\xB2; in an inelastic bounce, (1 \u2212 e\xB2) of KE turns into heat.","A sphere hitting clay at 2v carves a crater 4\xD7 deeper than at v.",e=>e.setSlider("Clay test impact speed",4),"Each bounce peaks at e\xB2 of the previous height while warming the floor.",e=>e.setSlider("Bounce restitution",.7),"Inside the kWh meter: disc speed measures Watts, total turns count kWh.","City Sankey pipes split 100% fuel input into useful work and ambient heat.",e=>e.setSlider("Household appliance load",2800),"Clay resistance force F_clay is modelled as uniform with penetration depth.",[{name:"4\xD7 Clay Crater Test",prompt:"Check quadratic \xBDmv\xB2 scaling at double speed.",state:{tabs:[0,0],sliders:{"Clay test impact speed":4}}},{name:"Heavy Home kWh Load",prompt:"Compare spinning disc watts vs cumulative kWh.",state:{tabs:[2,0],sliders:{"Household appliance load":2800}}}],{openPlay:"Switch to Section cutaway on the household kWh meter to distinguish Power (W) from Energy (kWh).",misconception:"Thinking doubling car speed only doubles braking distance (actually 4\xD7 work!).",dinnerQuestion:"Why does a car screeching at 80 km/h on the Bandra\u2013Worli Sea Link need four times the stopping distance of 40 km/h?",cambridgeUnit:"Unit 3 \xB7 Work, Quadratic KE & Power"}),atlas_ch08:l("Push heat input into the water\u2013steam phase transition plateau\u2014why does the thermometer stall while you keep heating?",e=>e.num("Added heat per kg",550)>=850&&e.num("Added heat per kg",550)<=3e3||e.interacted,e=>{let t=e.num("Matka water evaporated",1.5),a=t/100*226e4/((1-t/100)*4184);return`Matka: ${t.toFixed(1)}% evaporated \xD7 L_v \xF7 c_w \u2192 cools pot by \u2212${a.toFixed(1)} \xB0C (to ${(32-a).toFixed(1)} \xB0C)`},"During boiling or matka evaporation, incoming energy breaks hydrogen bonds (L_v = 2,260 kJ/kg) instead of raising kinetic energy.","Joule\u2019s falling weights churn water: 4,184 J warms 1 kg by 1 \xB0C.",e=>e.setSlider("Joule weight drops",30),"A 40 \xB0C bucket holds vastly more thermal energy Q = mc\u0394T than a 100 \xB0C spoon.",void 0,"A wool sweater traps dead air, blocking room heat from melting ice.","Evaporating 1.8% of water through porous matka clay cools the pot by ~10 \xB0C.",e=>e.setSlider("Matka water evaporated",1.8),"Calorimeter walls are treated as adiabatic outside the modelled heat flux.",[{name:"Boiling Flat Plateau",prompt:"Add latent heat at constant 100 \xB0C.",state:{tabs:[1,0],sliders:{"Added heat per kg":1500}}},{name:"Clay Matka Cooling",prompt:"Small sweat fraction cools water noticeably.",state:{tabs:[2,0],sliders:{"Matka water evaporated":1.8}}}],{openPlay:'Compare "100 \xB0C spoon vs 40 \xB0C bucket" to distinguish temperature from internal thermal energy.',misconception:"Assuming added heat MUST always raise temperature even during melting or boiling.",dinnerQuestion:"Why does drinking water stored in a Dharavi terracotta matka stay noticeably cooler in May humidity?",cambridgeUnit:"Unit 5 \xB7 Specific & Latent Heat"}),atlas_ch09:l("Sweep Barton\u2019s driver frequency past the pendulum array\u2014why does one hanging responder absorb a dramatic swing?",e=>Math.abs(e.num("Barton driver frequency",1.5)-2)<=.15||e.interacted,e=>{let t=e.num("Acoustic frequency",343);return`v_sound = f \u03BB \u2192 343 m/s = ${t} Hz \xD7 ${(343/t).toFixed(2)} m  |  Barton f_drive = ${e.num("Barton driver frequency",1.5).toFixed(2)} Hz`},"At resonance f_drive = f\u2080, pushes arrive in phase with velocity; in sound waves, air rings oscillate locally while compressions travel at 343 m/s.","On Barton\u2019s cord, only the responder matching the driver builds a huge swing.",e=>e.setSlider("Barton driver frequency",1.5),"Shifting f_drive to 2.0 Hz hands resonance to the next shorter pendulum.",e=>e.setSlider("Barton driver frequency",2),"Above 15 m/s crosswind, vortex shedding locks onto bridge deck twist.","Doubling acoustic frequency f halves wavelength \u03BB = v/f.",e=>e.setSlider("Acoustic frequency",500),"Sound propagation is modelled in dry air at 20 \xB0C (343 m/s).",[{name:"Barton Resonance Peak",prompt:"Match driver beat to a hanging pendulum.",state:{tabs:[0,0],sliders:{"Barton driver frequency":2}}},{name:"500 Hz Sound Wavelength",prompt:"Verify \u03BB = 343 / f spacing in air rings.",state:{tabs:[2,0],sliders:{"Acoustic frequency":500}}}],{openPlay:"Look closely at how non-resonant responders barely twitch compared to the matched length.",misconception:"Thinking air molecules travel all the way across a hall from singer to ear.",dinnerQuestion:"Why can a low train horn rattle just one loose windowpane in your Dadar flat while leaving thicker panes calm?",cambridgeUnit:"Unit 6 \xB7 Resonance & Acoustic Waves"}),atlas_ch10:l("Stop down the pinhole aperture for a sharper inverted candle, or swing Earth behind the Sun to reveal R\xF8mer\u2019s light delay!",e=>e.num("Pinhole aperture diameter",1.5)<=.6||e.num("Earth orbital angle",180)>=160||e.interacted,e=>{let t=e.num("Pinhole aperture diameter",1.5),a=e.num("Camera box depth",180),i=a/360;return`M = d_i \xF7 d_o = ${i.toFixed(2)}\xD7  |  blur = ${(t*(1+i)).toFixed(2)} mm  |  brightness \u221D d\xB2 = ${(t*t).toFixed(2)}`},"Straight rays from candle top and bottom cross at the pinhole to invert the image; across Earth\u2019s 2 AU orbit, light takes 16.6 min to cross.","We see non-luminous pages only when diffusely scattered rays enter our pupil.",void 0,"A 0.5 mm pinhole yields a crisp inverted image; a 4.5 mm hole blurs overlapping cones.",e=>e.setSlider("Pinhole aperture diameter",.5),"Deeper camera box d_i magnifies the inverted image linearly (M = d_i/d_o).","At conjunction (180\xB0), Io\u2019s eclipses arrive 16.6 minutes late across 2 AU.",e=>e.setSlider("Earth orbital angle",180),"Geometric ray optics omits wave diffraction below ~0.3 mm.",[{name:"Sharp 0.5 mm Pinhole",prompt:"Tighten hole diameter for crisp inversion.",state:{tabs:[0,0],sliders:{"Pinhole aperture diameter":.5}}},{name:"R\xF8mer 180\xB0 Io Eclipse",prompt:"Compare light delay across Earth\u2019s 2 AU orbit.",state:{tabs:[2,0],sliders:{"Earth orbital angle":180}}}],{openPlay:"Compare 0.5 mm vs 4.5 mm aperture on bright vs crispness trade-offs.",misconception:"Thinking a pinhole flips an image left-right only OR that human sight shoots rays out of the eye.",dinnerQuestion:"During a Mumbai solar eclipse under banyan leaves, why do hundreds of tiny gaps project crescent Suns on the pavement?",cambridgeUnit:"Unit 7 \xB7 Ray Geometry & Speed of Light"}),atlas_ch11:l("Rotate the Polaroid filter to find which axis snuffs out pond surface glare completely!",e=>Math.abs(e.num("Polaroid sunglass axis",90)-90)<=5||e.interacted,e=>{let t=e.num("Polaroid sunglass axis",90),a=Math.round(Math.pow(Math.cos(t*Math.PI/180),2)*100);return`Brewster \u03B8_B = 53.1\xB0  |  Malus cos\xB2(${t}\xB0) = ${a}% glare  |  Raman \u0394\u03BD\u0303 = ${e.num("Molecular bond vibration",459)} cm\u207B\xB9`},"Newton\u2019s inverted second prism recombines the spectrum into white light; Raman inelastic scattering shifts photon energy by a vibrational quantum.","Violet bends more than red in glass; Newton\u2019s second prism recombines them into white.",void 0,"Water glare at 53.1\xB0 is horizontally polarized; a 90\xB0 vertical Polaroid blocks it.",e=>e.setSlider("Polaroid sunglass axis",90),"Rotating the Polaroid to 0\xB0 transmits 100% of the surface glare.","Higher bond vibration frequency \u0394\u03BD\u0303 pushes the Raman Stokes line farther into the green.",e=>e.setSlider("Molecular bond vibration",1100),"Crown glass dispersion uses a two-term Cauchy relation.",[{name:"Zero Glare 90\xB0 Filter",prompt:"Block horizontally polarised pond reflection.",state:{tabs:[1,0],sliders:{"Polaroid sunglass axis":90}}},{name:"Raman Vibrational Shift",prompt:"Tune molecular shift away from Rayleigh peak.",state:{tabs:[2,0],sliders:{"Molecular bond vibration":1100}}}],{openPlay:"Twist the Polaroid axis 90\xB0 across water glare first\u2014prove light is a transverse wave!",misconception:"Thinking glass prisms manufacture new colours instead of separating wavelengths already in white light.",dinnerQuestion:"Why did C. V. Raman notice the deep sapphire Caribbean sea and then discover scattered sky photons shifting colour?",cambridgeUnit:"Unit 7 \xB7 Dispersion, Polarisation & Scattering"}),atlas_ch12:l("Step up circuit voltage across ohmic vs filament loads, or inspect how the thicker Earth wire trips a household fuse during a live fault!",e=>e.num("Applied circuit voltage",3.5)>=3.5||e.interacted,e=>{let t=e.num("Applied circuit voltage",3.5),a=e.num("Earth fault loop resistance",2);return`At V = ${t.toFixed(1)} V: I_ohmic = ${(t/10).toFixed(2)} A  |  230 V fault: I = 230 \xF7 ${a.toFixed(1)} \u03A9 = ${(230/a).toFixed(0)} A (blows 15 A fuse!)`},"The top Earth pin is longer (connects first) and thicker (R_E \u2248 2 \u03A9) so a live-to-case fault triggers a 115 A surge that melts the fuse immediately.","A charged comb polarizes neutral paper bits, pulling closer +q upward.",e=>e.setSlider("Charged comb height",1.4),"A battery pumps the wire\u2019s existing conduction electrons around a closed loop.",void 0,"Heating a tungsten filament scatters electrons and bends its I\u2013V curve.","A 2 \u03A9 Earth wire diverts fault current and blows the 15 A fuse safely.",e=>e.setSlider("Earth fault loop resistance",2),"Mains voltage is 230 V RMS with a 15 A fuse threshold.",[{name:"Ohmic vs Filament I\u2013V",prompt:"See hot filament bend away from Ohm\u2019s line.",state:{tabs:[1,0],sliders:{"Applied circuit voltage":4}}},{name:"3-Pin Earth Fault Surge",prompt:"Low-R Earth path forces fault current past 15 A.",state:{tabs:[2,0],sliders:{"Earth fault loop resistance":2}}}],{openPlay:"Zoom into the Indian 3-pin plug in X-ray view\u2014notice which pin enters the socket first.",misconception:"Thinking a battery creates brand-new electrons instead of pumping free electrons already inside copper wires.",dinnerQuestion:"Why is the top Earth pin on an Indian 3-pin AC plug BOTH thicker and longer than the Live and Neutral pins?",cambridgeUnit:"Unit 8 \xB7 Circuits, I\u2013V & Earthing Safety"}),atlas_ch13:l("Strengthen the external field to align iron domains, or crank armature current to boost motor torque!",e=>e.num("External magnetizing field",.45)>=.75||e.num("DC motor armature current",3.5)>=5||e.interacted,e=>`\u03C4_max = N I A B = ${(20*e.num("DC motor armature current",3.5)*.02*.5).toFixed(2)} N\xB7m  |  c = 1/\u221A(\u03BC\u2080\u03B5\u2080) = 2.998 \xD7 10\u2078 m/s`,"Split-ring commutator halves swap brush polarity every 180\xB0 to keep torque one-way; in free space, E and B regenerate each other at speed c.","Microscopic magnetic domains inside soft iron align as B_ext rises.",e=>e.setSlider("External magnetizing field",.85),"Opposite currents on left and right coil branches create a continuous torque couple.",e=>e.setSlider("DC motor armature current",5),"The split-ring commutator reverses coil current every half-turn.","Perpendicular E and B waves oscillate in phase at speed c.",e=>e.setSlider("EM wave frequency",2.25),"Stator poles produce a uniform horizontal B-field across the rotor gap.",[{name:"Aligned Iron Domains",prompt:"Saturate soft-iron dipole arrows with B_ext.",state:{tabs:[0,0],sliders:{"External magnetizing field":.85}}},{name:"High-Torque DC Motor",prompt:"Inspect split-ring flip every half revolution.",state:{tabs:[1,2],sliders:{"DC motor armature current":5}}}],{openPlay:"Switch DC motor to Section cutaway to watch the split-ring commutator swap brush contact every 180\xB0.",misconception:"Thinking DC motors keep spinning one way without flipping current inside the rotating loop.",dinnerQuestion:"Inside a ceiling fan motor running steadily in your study, what stops the armature from flipping back after half a turn?",cambridgeUnit:"Unit 8 \xB7 Domains, Motors & EM Waves"}),atlas_ch14:l("Shift the Full Moon away from the orbital Line of Nodes to discover why most Full Moons miss Earth\u2019s shadow!",e=>e.num("Full Moon angle",0)>=30||e.interacted,e=>{let t=e.num("Earth axial tilt",23.4),a=e.num("Full Moon angle",0),i=60*Math.sin(5.14*Math.PI/180)*Math.sin(a*Math.PI/180);return`Tilt \u03B5 = ${t.toFixed(1)}\xB0  |  Lunar 5.14\xB0 tilt at ${a}\xB0 from node \u2192 shadow miss = ${i.toFixed(2)} R_E`},"At r = 60 R_E, the Moon\u2019s 5.14\xB0 orbit tilt carries it up to 5.4 R_E above or below Earth\u2019s shadow cone except near the Line of Nodes.","As Earth spins West-to-East at 15\xB0/h, our local horizon boat turns eastward into sunlight.",void 0,"Earth\u2019s 23.4\xB0 axis stays parallel in space all year, driving the seasons.",e=>e.setSlider("Orbital longitude",90),"In December (270\xB0), the same parallel axis tilts the Northern Hemisphere away from the Sun.","Away from the nodes (60\xB0), the 5.14\xB0 tilt lifts the Full Moon clear of Earth\u2019s shadow.",e=>e.setSlider("Full Moon angle",60),"3D orbital sizes are scaled for visibility while numerical readouts use exact 60 R_E geometry.",[{name:"Node Lunar Eclipse",prompt:"Align 0\xB0 at the Line of Nodes into Earth\u2019s shadow.",state:{tabs:[2,0],sliders:{"Full Moon angle":0}}},{name:"Clear Full Moon (60\xB0)",prompt:"5.14\xB0 lunar tilt lifts Moon clear of umbra.",state:{tabs:[2,0],sliders:{"Full Moon angle":60}}}],{openPlay:"Orbit edge-on to the ecliptic plane so you see why the 5.14\xB0 tilted orbit misses the umbra cone.",misconception:"Asking why we don\u2019t see a lunar eclipse every single Full Moon month.",dinnerQuestion:"Since Earth always casts a long shadow opposite the Sun, why can Mumbai go months between visible lunar eclipses?",cambridgeUnit:"Unit 9 \xB7 Eclipses & Orbital Inclination"}),atlas_ch15:l("Shift light into ultraviolet to trigger photoemission, or push a white dwarf\u2019s mass toward the Chandrasekhar limit!",e=>e.num("Incident light wavelength",340)<=380||e.num("White dwarf mass",.85)>=1.3||e.interacted,e=>{let t=e.num("Incident light wavelength",340),a=1239.84/t,i=e.num("White dwarf mass",.85);return`Photon hf = ${a.toFixed(2)} eV (K_max = ${Math.max(0,a-2.3).toFixed(2)} eV)  |  White dwarf M = ${i.toFixed(2)} M_\u2609 (limit 1.44 M_\u2609)`},"Light exchanges energy in quanta E = hf; in a white dwarf, Pauli electron degeneracy supports the star until relativistic collapse at 1.44 M_\u2609.","Red light (1.91 eV < \u03C6) cannot eject electrons; UV (4.13 eV) discharges the gold leaf.",e=>e.setSlider("Incident light wavelength",300),"Single photons land as discrete dots yet accumulate into wave interference fringes.",e=>e.setSlider("Single-photon exposure",195),"Inside solar p\u2013p fusion, 0.7% of proton mass becomes 26.7 MeV via \u0394E = \u0394mc\xB2.","Raising white-dwarf mass toward 1.44 M_\u2609 shrinks its radius dramatically.",e=>e.setSlider("White dwarf mass",1.38),"Work function \u03C6 = 2.30 eV; white dwarf radius uses the Chandrasekhar relativistic formula.",[{name:"UV Photoelectric Drop",prompt:"Short-wavelength photons exceed \u03C6 = 2.30 eV.",state:{tabs:[0,0],sliders:{"Incident light wavelength":300}}},{name:"Near Chandrasekhar 1.38 M_\u2609",prompt:"Watch relativistic degeneracy squeeze white dwarf.",state:{tabs:[2,0],sliders:{"White dwarf mass":1.38}}}],{openPlay:"Compare low-energy red beam vs UV photons\u2014why doesn\u2019t waiting longer help red light eject electrons?",misconception:"Thinking brighter red light eventually knocks electrons loose if you crank up intensity enough.",dinnerQuestion:"How did Subrahmanyan Chandrasekhar deduce on a boat from Madras to England that massive dying stars cannot stay white dwarfs?",cambridgeUnit:"Unit 9 \xB7 Quanta, Fusion & Stellar Fate"}),vectors:{challenge:{prompt:"Switch to the Parallelogram law with P = 60 N and Q = 80 N, and discover the angle \u03B8 where the resultant R is exactly 100 N.",check:e=>e.tab(0)===1&&Math.abs(e.num("Angle \u03B8",50)-90)<=5&&Math.abs(e.num("Arrow P",80)-60)<=5&&Math.abs(e.num("Arrow Q",60)-80)<=5},presets:[{name:"Perpendicular Components",prompt:"Split one 80 N force into horizontal & vertical shadows.",state:{tabs:[0],sliders:{"Angle \u03B8":37,"Arrow P":80}}},{name:"Ramp Component Split",prompt:"See why steeper ramps increase down-slope pull.",state:{tabs:[2],sliders:{"Angle \u03B8":30,"Arrow P":100}}}],mentorTips:{openPlay:"Ask what happens to R_x when \u03B8 reaches 90\xB0 and why two forces can cancel or add depending on angle.",misconception:"Simply adding 60 N + 80 N = 140 N regardless of direction.",dinnerQuestion:"If you and a friend pull a heavy box along two ropes 90\xB0 apart with 60 N and 80 N, why is the combined pull 100 N instead of 140 N?",cambridgeUnit:"Unit 3 \xB7 Force Vectors & Resultants"},yourNumbers:e=>{let t=e.num("Angle \u03B8",50),a=t*Math.PI/180,i=e.num("Arrow P",80),n=e.num("Arrow Q",60);if(e.tab(0)===0)return`R_x = ${i} cos ${t}\xB0 = ${(i*Math.cos(a)).toFixed(1)} N  |  R_y = ${i} sin ${t}\xB0 = ${(i*Math.sin(a)).toFixed(1)} N  |  \u221A(R_x\xB2 + R_y\xB2) = ${i.toFixed(1)} N`;if(e.tab(0)===1){let s=Math.sqrt(i*i+n*n+2*i*n*Math.cos(a));return`R = \u221A(${i}\xB2 + ${n}\xB2 + 2\xB7${i}\xB7${n} cos ${t}\xB0) = ${s.toFixed(1)} N`}let r=Math.min(t,75),o=r*Math.PI/180;return`Down-slope: mg sin ${r}\xB0 = ${(i*Math.sin(o)).toFixed(1)} N  |  Into slope: mg cos ${r}\xB0 = ${(i*Math.cos(o)).toFixed(1)} N`},cutaway:"Every 2D vector equation is two independent 1D equations at right angles: what happens along x has zero projection along y because cos 90\xB0 = 0.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: One tilted arrow R casts two perpendicular shadows, R_x = R cos \u03B8 and R_y = R sin \u03B8.",act:e=>{e.selectTab(0,0),e.setSlider("Angle \u03B8",40),e.setSlider("Arrow P",80)}},{title:"2. Close-up",caption:"2/5 Close-up: In the Parallelogram Law, projecting P into P cos \u03B8 and P sin \u03B8 builds a right triangle of base Q + P cos \u03B8.",act:e=>{e.selectTab(0,1),e.setSlider("Angle \u03B8",60),e.setSlider("Arrow P",60),e.setSlider("Arrow Q",80)}},{title:"3. Cut-away",caption:"3/5 Cut-away: At \u03B8 = 90\xB0, cos 90\xB0 = 0 so the 2PQ cos \u03B8 alignment bonus vanishes and R = \u221A(P\xB2 + Q\xB2).",cutaway:!0,act:e=>e.setSlider("Angle \u03B8",90)},{title:"4. Side-on trend",caption:"4/5 Trend: On a tilted ramp, gravity mg splits into mg sin \u03B8 along the slope and mg cos \u03B8 into the boards.",act:e=>{e.selectTab(0,2),e.setSlider("Angle \u03B8",30)}},{title:"5. Your turn",caption:"5/5 Your turn: Sweep \u03B8 from 0\xB0 to 180\xB0 or test ramp components.",cutaway:!1}],idealised:"Vectors here lie in a flat 2D plane; in 3D space a third perpendicular component R_z joins so R = \u221A(R_x\xB2 + R_y\xB2 + R_z\xB2)."},atwood:{challenge:{prompt:"Choose two unequal pulley masses that dilute downward acceleration to roughly one-tenth of free fall (a \u2248 0.98 m/s\xB2).",check:e=>{let t=e.num("Left mass m\u2081",.55),a=e.num("Right mass m\u2082",.45),i=Math.abs((t-a)*9.8/(t+a));return Math.abs(i-.98)<=.12&&e.interacted}},presets:[{name:"Balanced Pulley (a = 0)",prompt:"Equal 0.50 kg masses hang in zero-acceleration tension.",state:{sliders:{"Left mass m\u2081":.5,"Right mass m\u2082":.5}}},{name:"Steep Imbalance (0.8 vs 0.3)",prompt:"Compare rope tension T against both weights m\u2081g and m\u2082g.",state:{tabs:[1],sliders:{"Left mass m\u2081":.8,"Right mass m\u2082":.3}}}],mentorTips:{openPlay:"Ask whether rope tension T equals m\u2081g, m\u2082g, or lies strictly between them while moving.",misconception:"Assuming the heavier falling mass pulls the rope with its full weight m\u2081g (ignoring that it is accelerating downward!).",dinnerQuestion:"In a lift accelerating downward, do you feel heavier, lighter, or unchanged on a bathroom scale?",cambridgeUnit:"Unit 3 \xB7 Coupled Masses & Tension"},yourNumbers:e=>{let t=e.num("Left mass m\u2081",.55),a=e.num("Right mass m\u2082",.45),i=(t-a)*9.8/(t+a),n=2*t*a*9.8/(t+a);return`a = (${t.toFixed(2)} \u2212 ${a.toFixed(2)}) \xD7 9.8 \xF7 ${(t+a).toFixed(2)} = ${i.toFixed(2)} m/s\xB2  |  T = ${n.toFixed(2)} N`},cutaway:"Unfolding the rope reveals a 1D coupled train: internal tensions +T and \u2212T cancel across the rope while the external weight difference (m\u2081 \u2212 m\u2082)g accelerates the combined inertia m\u2081 + m\u2082.",watch:[{title:"1. Wide view",caption:"1/5 Wide shot: Two nearly equal masses (0.55 kg and 0.45 kg) dilute free fall to a gentle 0.98 m/s\xB2.",act:e=>{e.setSlider("Left mass m\u2081",.55),e.setSlider("Right mass m\u2082",.45)}},{title:"2. Close-up",caption:"2/5 Close-up: Equal masses (0.50 kg each) give zero net driving force and T = mg = 4.90 N.",act:e=>{e.setSlider("Left mass m\u2081",.5),e.setSlider("Right mass m\u2082",.5)}},{title:"3. Cut-away",caption:"3/5 Cut-away: Inside the Tension Sandwich, T must beat the lighter weight m\u2082g so m\u2082 rises, yet stay below m\u2081g so m\u2081 falls.",cutaway:!0,act:e=>{e.selectTab(0,1),e.setSlider("Left mass m\u2081",.8),e.setSlider("Right mass m\u2082",.3)}},{title:"4. Side-on trend",caption:"4/5 Trend: A large imbalance (1.00 kg vs 0.20 kg) drives acceleration up to two-thirds of g (6.53 m/s\xB2).",act:e=>{e.selectTab(0,0),e.setSlider("Left mass m\u2081",1),e.setSlider("Right mass m\u2082",.2)}},{title:"5. Your turn",caption:"5/5 Your turn: Adjust m\u2081 and m\u2082 to test any mass ratio on Atwood\u2019s pulley.",cutaway:!1}],idealised:"The rope is treated as massless and unstretchable, and the pulley wheel as frictionless and massless (a real pulley adds rotational inertia I/R\xB2 to the denominator)."}};typeof window<"u"&&(window.__liveEnhancements=g);export{g as ENHANCEMENTS};
